x_comment(x_InducedActionAlternation,"An alternation in which the transitive form specifies an action that the causer which, when performed by the subject, also induces the same action to happen to the object.  The transitive forms also must have an overt or understood directional phrase accompanying them.  For example, in 'Kim drove Sandy to the airport', 'Kim' causes 'Sandy' to be transported while in the alternation 'Kim drove to the airport', 'Kim' only causes herself to be transported.") :- x_cid(a65b1273c27a7c).
xc_microtheory(a65b1273c27a7c,x_GeneralLexiconMt).
