x_comment(x_morphologicallyDerivedFrom,"#$morphologicallyDerivedFrom relates a #$DerivedWord to its #$BaseWordForm constituent. Example: (#$morphologicallyDerivedFrom #$Unhappy-TheWord #$Happy-TheWord) means that #$Unhappy-TheWord is derived from the word #$Happy-TheWord.") :- x_cid(a65b1273c27a89).
xc_microtheory(a65b1273c27a89,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a89,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
