xc_mapping_rows(a65b1273c27a89,[]).
x_comment(x_nameSuffix,"Predicate indicating the different suffixes that may go on a person's name; e.g., jr., III, esq., Ph.D., Ed.D., M.A., etc.") :- x_cid(a65b1273c27a8a).
xc_microtheory(a65b1273c27a8a,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a8a,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
