x_comment(x_gerund,"A #$SpeechPartPredicate (q.v.) and a specialization of \n#$massNumber-Generic. (#$gerund WORD STRING) means that STRING is the gerund form \nof WORD. The regular gerund is formed from the infinitive \nverb form with an `ing' suffix. Verbs in the Cyc lexicon will \nhave a #$gerund entry only if they are irregular.  Regular \nforms are generated by the morphology component.") :- x_cid(a65b1273c27a8b).
xc_microtheory(a65b1273c27a8b,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a8b,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a8b,1602).
xc_kb_names(a65b1273c27a8b,[]).
xc_mapping_rows(a65b1273c27a8b,[]).
x_disjointWith('x_Determiner-Indefinite','x_Determiner-Definite') :- x_cid(a65b1273c27a8c).
xc_microtheory(a65b1273c27a8c,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a8c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
