xc_kb_names(a65b1273c27a8c,[]).
xc_mapping_rows(a65b1273c27a8c,[]).
x_comment('x_placeName-Standard',"(#$placeName-Standard PLACE NAME) means that NAME is the name of PLACE most standardly used to refer to PLACE. The NIMA Geographic Names DB is a good reference for standard names; use the category Geographic Name for representation with this predicate. For short forms for PLACE, use #$placeName-ShortForm. For nicknames for PLACE use #$nicknames. For names of PLACE which are none of these, just use #$nameString. Remember to make the assertions in the approproate language mt. Examples: (#$placeName-Standard #$CityOfNewYorkNY \"New York City\"); (#$placeName-ShortForm #$CityOfNewYorkNY \"New York\"); (#$nicknames #$CityOfNewYorkNY \"the Big Apple\"); (#$initialismString #$CityOfNewYorkNY \"NYC\"); (#$nameString #$CityOfNewYorkNY \"the City of New York\").") :- x_cid(a65b1273c27a8d).
xc_microtheory(a65b1273c27a8d,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a8d,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a8d,1609).
xc_kb_names(a65b1273c27a8d,[]).
xc_mapping_rows(a65b1273c27a8d,[]).
x_comment(x_nnRule,"(nnRule NAME CONDITION_TEMPLATE MEANING_TEMPLATE) means that for a noun-noun pair of words (WORD1 and WORD2) if they have nominal denotations :NOUN1 and :NOUN2, and the CONDITION_TEMPLATE matches those denotations, then the MEANING_TEMPLATE, filled in with those meanings, is the meaning for the noun-noun pair.  The string, NAME, should be an example noun-noun compound that this form applies to.") :- x_cid(a65b1273c27a8e).
xc_microtheory(a65b1273c27a8e,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a8e,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a8e,1610).
xc_kb_names(a65b1273c27a8e,[]).
xc_mapping_rows(a65b1273c27a8e,[]).
x_comment(x_VerbClass,"Collection of all verb classes. Every verb sense belongs to a verb class and inherits from its verb class general semantic and\n\nsyntactic rules. When creating a new verb or verb sense, place it in\n\nits verb class or classes using #$hasVerbAsMember, e.g.\n\n(#$hasVerbAsMember #$Give-VerbClass #$Give-TheWord 0).") :- x_cid(a65b1273c27a8f).
xc_microtheory(a65b1273c27a8f,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a8f,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a8f,1611).
xc_kb_names(a65b1273c27a8f,[]).
xc_mapping_rows(a65b1273c27a8f,[]).
x_comment(x_hasVerbAsMember,"(#$hasVerbAsMember VERBCLASS LEXICALWORD SENSENUMBER) means that VERBCLASS has LEXICALWORD with sense SENSENUMBER as a member. This predicate is used to link up verbs with the classes to which they belong.  See Beth Levin's text *English Verb Classes and Alternations* for more on how to group verbs into classes -- the NL Dept. library has a copy.  When using this predicate, remember that while a particular verb may belong to many different verb classes, a particular verb sense belongs to only one #$VerbClass.  The following example asserts that sense 0 of the lexical word #$Give-TheWord is a member of the #$Give-VerbClass.  (Note: To find out which sense you need, look at the #$denotation and various semTrans-type assertions the word is involved in.) (#$hasVerbAsMember #$Give-VerbClass #$Give-TheWord 0)") :- x_cid(a65b1273c27a90).
xc_microtheory(a65b1273c27a90,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a90,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a90,1618).
xc_kb_names(a65b1273c27a90,[]).
xc_mapping_rows(a65b1273c27a90,[]).
x_comment(x_relevantToVerbMapping,"(#$relevantToVerbMapping REIFIABLETERM LEXICALWORD WORDSENSENUMBER).  This predicate is used in work flow to alert someone doing OE or NL work on a particular verb sense to the fact that a fort (or many forts if there are many such assertions) are relevant or could be seen as relevant to representing the verb sense in question.  For example, if I thought that the collection #$GivingSomething would most likely be involved in the semantic representation of the word #$Give-TheWord (with sense number 0 -- check the various #$denotations and semTrans assertions that a word is involved in to see what sense number corresponds to the sense to be represented), I would make this assertion (#$relevantToVerbMapping #$GivingSomething #$Give-TheWord 0).") :- x_cid(a65b1273c27a91).
xc_microtheory(a65b1273c27a91,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a91,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a91,1619).
xc_kb_names(a65b1273c27a91,[]).
xc_mapping_rows(a65b1273c27a91,[]).
x_comment('x_Give-VerbClass',"The verbs in this class are all members of a larger class -- verbs of change of possession (section 13 of Levin text). In many cases the sense of \"possession\" in this larger class is broadly construed; e.g. in \"Sally administers the medicine to Fred\", \"administers\" function as a verb of this class, even though Sally may not *own* the medicine she is administering.  The #$Give-VerbClass is differentiated from the #$ContributeVerbClass (also a class of verbs of change of possession) syntactically; the contribute verbs do not allow\n\nthe dative alternation while the give verbs do.  When verbs of this class appear with a prepositional phrase, the phrase must begin with \"to\". Note that one may also make a case for a subtle semantic difference between the two; the give verbs all involve a voluntary transfer of possession by the subject (i.e. possibly has\n\nbenefits for the giver) while the contribute verbs, many of them at least,\n\ninvolve a possibly reluctant transfer of possession (e.g. relinquish,\n\nreimburse, restore, etc. as opposed to give, feed, lease, etc.).") :- x_cid(a65b1273c27a92).
xc_microtheory(a65b1273c27a92,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a92,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a92,1620).
xc_kb_names(a65b1273c27a92,[]).
xc_mapping_rows(a65b1273c27a92,[]).
x_comment(x_preferredTermStrings,"Use this predicate to record the preferred way of referring to a Fort. This is a specPred of #$termStrings so there is no need to make both a #$termStrings and a #$preferredTermStrings assertion using the same string. Do, however, try to make as many termStrings assertions as possible for a given Fort. Whenever there are at least two #$termStrings assertions, there should be a #$preferredTermStrings assertion specifying the string that should be used in generation. See the comment on #$termStrings for more on how to use that predicate.") :- x_cid(a65b1273c27a93).
xc_microtheory(a65b1273c27a93,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a93,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a93,1629).
xc_kb_names(a65b1273c27a93,[]).
xc_mapping_rows(a65b1273c27a93,[]).
x_comment(x_abbreviationForString,"(#$abbreviationForString STRING ABBREVIATION) means that ABBREVIATION is an abbreviation for STRING.  Example -- (#$abbreviationForString \"department\" dept\").") :- x_cid(a65b1273c27a94).
xc_microtheory(a65b1273c27a94,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a94,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a94,1630).
xc_kb_names(a65b1273c27a94,[]).
xc_mapping_rows(a65b1273c27a94,[]).
x_comment(x_abbreviationForMultiWordString,"(#$abbreviationForMultiWordString STRING LEXICALWORD POS ABBREVIATION) means that ABBREVIATION is an abbreviation for the multi-word phrase picked out by STRING + POS part of speech of   LEXICALWORD. Example --  (#$abbreviationForMultiWordString (#$TheList (\"cubic\")) #$Foot-TheWord #$CountNoun \"cu ft\")") :- x_cid(a65b1273c27a95).
xc_microtheory(a65b1273c27a95,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a95,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a95,1631).
xc_kb_names(a65b1273c27a95,[]).
xc_mapping_rows(a65b1273c27a95,[]).
x_comment(x_abbreviationForCompoundString,"(#$abbreviationForCompoundString LEXICALWORD STRING POS ABBREVIATION) means that ABBREVIATION is an abbreviation for the compound phrase picked out by POS part of speech of LEXICALWORD + STRING.  Example --  (#$abbreviationForCompoundString #$Mile-TheWord (#$TheList (\"per\" \"hour\")) #$CountNoun \"m/h\").") :- x_cid(a65b1273c27a96).
xc_microtheory(a65b1273c27a96,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a96,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a96,1632).
xc_kb_names(a65b1273c27a96,[]).
xc_mapping_rows(a65b1273c27a96,[]).
x_comment(x_abbreviationForLexicalWord,"(#$abbreviationForLexicalWord LEXICALWORD POS ABBREVIATION) means that ABBREVIATION is an abbreviation for the POS form of the word LEXICALWORD. Example --  (#$abbreviationForLexicalWord #$Department-TheWord #$singular \"dept\").  For mapping phrases to abbreviation strings use either #$abbreviationForMultiWordString or #$abbreviationForCompoundString.") :- x_cid(a65b1273c27a97).
xc_microtheory(a65b1273c27a97,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a97,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a97,1633).
xc_kb_names(a65b1273c27a97,[]).
xc_mapping_rows(a65b1273c27a97,[]).
x_comment(x_LexicalMtForLanguageFn,"The expression (#$LexicalMtForLanguageFn LANGUAGE) denotes the lexical Mt for the language LANGUAGE. For example, (#$LexicalMtForLanguageFn #$EnglishLanguage) denotes the lexical Mt for the english language. Since this one is so widely used, though, we'll stay with #$EnglishMt.") :- x_cid(a65b1273c27a98).
xc_microtheory(a65b1273c27a98,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a98,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a98,1634).
xc_kb_names(a65b1273c27a98,[]).
xc_mapping_rows(a65b1273c27a98,[]).
x_comment(x_WordInLanguageFn,"The expression (#$WordInLanguageFn LANGUAGE) denotes a collection of lexical words in the language LANGUAGE. For example, (#$isa #$Hello-TheWord (#$WordInLanguageFn #$EnglishLanguage)) says that the word \"hello\" is a word in the english language.") :- x_cid(a65b1273c27a99).
xc_microtheory(a65b1273c27a99,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a99,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a99,1635).
xc_kb_names(a65b1273c27a99,[]).
xc_mapping_rows(a65b1273c27a99,[]).
x_comment(x_genStringAssertion,"(#$genStringAssertion TERM ASRTN) means that a ASRTN should be used in generation for the Cyc TERM (or derived term in the case of functions).  #$genPhrase and #$preferredGenUnit trump #$genStringAssertion which, in turn, trumps everything else.") :- x_cid(a65b1273c27a9a).
xc_microtheory(a65b1273c27a9a,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a9a,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a9a,1636).
xc_kb_names(a65b1273c27a9a,[]).
xc_mapping_rows(a65b1273c27a9a,[]).
x_comment('x_Substance-SourceAlternation',"An #$ObjOfTrans-SubjOfIntrans alternation in which both the transitive and intransitive forms take two arguments; a source and a subtance emitted.  Example -- \"Heat radiates from the sun.\" \"The sun radiates heat.\"") :- x_cid(a65b1273c27a9b).
xc_microtheory(a65b1273c27a9b,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a9b,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a9b,1637).
xc_kb_names(a65b1273c27a9b,[]).
xc_mapping_rows(a65b1273c27a9b,[]).
x_comment(x_UnexpressedObjectAlternation,"An alternation in which the subjects of the transitive and intransitive forms respectively are related to the verb in the same way.  In the intransitive form the object is unexpressed but understood. Example: Fred flossed his teeth. / Fred flossed.") :- x_cid(a65b1273c27a9c).
xc_microtheory(a65b1273c27a9c,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a9c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a9c,1638).
xc_kb_names(a65b1273c27a9c,[]).
xc_mapping_rows(a65b1273c27a9c,[]).
x_comment(x_ConativeAlternation,"An alternation in which the object in the transitive form is the object of a prepositional phrases headed by \"at\" in the intransitive form.  These verbs describe attempted actions. Example: Sally swatted the fly. / Sally swatted at the fly.  Note that in Cyc we represent the latter with the frame (#$PPCompFrameFn #$TransitivePPFrameType #$At-TheWord)).") :- x_cid(a65b1273c27a9d).
xc_microtheory(a65b1273c27a9d,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a9d,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a9d,1639).
xc_kb_names(a65b1273c27a9d,[]).
xc_mapping_rows(a65b1273c27a9d,[]).
x_comment(x_NonTransitiveAlternationType,"Each instance of this collection is a type of alternation which does not involve a change in the transitivity of the verb. Example: The transitive 'NP1 V NP2 \"to\" NP3' structure may alternate with 'NP1 V NP3 NP2'.  There are other possibilities as well.") :- x_cid(a65b1273c27a9e).
xc_microtheory(a65b1273c27a9e,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a9e,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a9e,1640).
xc_kb_names(a65b1273c27a9e,[]).
xc_mapping_rows(a65b1273c27a9e,[]).
x_comment(x_LocativeAlternation,"The alternation between the structure 'NP1 V NP2 [P1 NP3]' and the structure 'NP1 V NP3 [P2 NP2].'  These verbs describe putting things on surfaces or in containers or removing them from such.  Possible arguments to these verbs include the thing moved and the location to which it is moved. When the location argument is not the object of a prepositional phrase, the location is completely affected by the action. Example: Fred sprayed paint on the wall. / Fred sprayed the wall with paint.") :- x_cid(a65b1273c27a9f).
xc_microtheory(a65b1273c27a9f,x_GeneralLexiconMt).
xc_source_file(a65b1273c27a9f,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27a9f,1641).
xc_kb_names(a65b1273c27a9f,[]).
xc_mapping_rows(a65b1273c27a9f,[]).
x_comment(x_CreationAndTransformationAlternation,"These alternations involve verbs of creation and transformation.  Each spec of #$CreationAndTransformationAlternation has both a transitive and intransitive form.  See #$CreationAndTransformationTransitiveAlternation and #$CreationAndTransformationIntransitiveAlternation for these.") :- x_cid(a65b1273c27aa0).
xc_microtheory(a65b1273c27aa0,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aa0,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aa0,1642).
xc_kb_names(a65b1273c27aa0,[]).
xc_mapping_rows(a65b1273c27aa0,[]).
x_comment(x_CreationAndTransformationTransitiveAlternation,"The alternation between the structure 'NP1 V NP2 \"into\" NP3' and 'NP1 V NP2 \"from\" NP4 \"into\" NP3.' These forms include an agent argument.  Example: Sally transformed her house into a palace. / Sally transformed her house from a pig sty into a palace.") :- x_cid(a65b1273c27aa1).
xc_microtheory(a65b1273c27aa1,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aa1,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aa1,1643).
xc_kb_names(a65b1273c27aa1,[]).
xc_mapping_rows(a65b1273c27aa1,[]).
x_comment(x_CreationAndTransformationIntransitiveAlternation,"The alternation between the structure 'NP1 V \"into\" NP2' and 'NP2 V \"from\" NP1.' There is no agent argument.  Example: The egg hatched into a bird. / A bird hatched from that egg.") :- x_cid(a65b1273c27aa2).
xc_microtheory(a65b1273c27aa2,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aa2,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aa2,1644).
xc_kb_names(a65b1273c27aa2,[]).
xc_mapping_rows(a65b1273c27aa2,[]).
x_comment(x_ReciprocalAlternation,"These alternations involve verbs that describe the same effects for each of their arguments. Each spec of #$ReciprocalAlternation has both a transitive and intransitive form. See #$ReciprocalTransitiveAlternation and #$ReciprocalIntransitiveAlternation for these.") :- x_cid(a65b1273c27aa3).
xc_microtheory(a65b1273c27aa3,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aa3,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aa3,1645).
xc_kb_names(a65b1273c27aa3,[]).
xc_mapping_rows(a65b1273c27aa3,[]).
x_comment(x_ReciprocalTransitiveAlternation,"The alternation between the structure 'NP1 V NP2 [P NP3]' and 'NP1 V [NP2 \"and\" NP3].' There is an agent argument.  In the form without a PP phrase, the arguments must be of comparable status.  Example: Sally taped the picture to the wall. / *(not) Sally taped the picture and the wall. Fred mixed the milk with the coffee. /  Fred mixed the milk and the coffee.") :- x_cid(a65b1273c27aa4).
xc_microtheory(a65b1273c27aa4,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aa4,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aa4,1646).
xc_kb_names(a65b1273c27aa4,[]).
xc_mapping_rows(a65b1273c27aa4,[]).
x_comment(x_ReciprocalIntransitiveAlternation,"The alternation between the structure 'NP1 V [P NP2]' and '[NP1 \"and\" NP2] V.' There is no agent argument.  In the form without a PP phrase, the arguments must be of comparable status.  Example: The car collided with the fence.  *(not) The car and the fence collided.  Sally chatted with Fred. / Sally and Fred chatted.") :- x_cid(a65b1273c27aa5).
xc_microtheory(a65b1273c27aa5,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aa5,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aa5,1647).
xc_kb_names(a65b1273c27aa5,[]).
xc_mapping_rows(a65b1273c27aa5,[]).
x_comment('x_With-AgainstAlternation',"The alternation between the structure 'NP1 V NP2 \"against\" NP3' and 'NP1 V NP3 \"with\" NP2.' There are always three arguments in this construction; an agent,a location, and an instrument.  The agent is always expressed as the subject. When the location argument is expressed as the object of a prepositional phrase, that phrase is headed by \"against.\" There is no intransitive counterpart to this alternation. Example: Fred pounded the gem against the rock. / Fred pounded the rock with the gem.") :- x_cid(a65b1273c27aa6).
xc_microtheory(a65b1273c27aa6,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aa6,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aa6,1648).
xc_kb_names(a65b1273c27aa6,[]).
xc_mapping_rows(a65b1273c27aa6,[]).
x_comment(x_LinguisticRegister,"A #$LinguisticRegister is a style of language use conventionally associated with particular topics or socio-professional situations. Common examples have been given names ending in `-ese', for example, Legalese, but there are many more linguistic registers than those with such names. #$LinguisticRegisters may be thought of as properties of languages, but they are not properties of individual expressions or of language users.") :- x_cid(a65b1273c27aa7).
xc_microtheory(a65b1273c27aa7,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aa7,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aa7,1649).
xc_kb_names(a65b1273c27aa7,[]).
xc_mapping_rows(a65b1273c27aa7,[]).
x_comment('x_LegalLanguage-Register',"This is the style of discourse conventionally associated with the legal profession. It is characterized by a preference for redundancy, convoluted sentence structure, and hedging.") :- x_cid(a65b1273c27aa8).
xc_microtheory(a65b1273c27aa8,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aa8,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aa8,1650).
xc_kb_names(a65b1273c27aa8,[]).
xc_mapping_rows(a65b1273c27aa8,[]).
x_comment('x_MedicalLanguage-Register',"This is the style of discourse conventionally associated with the medical profession. It is characterized by a preference for Greco-Latin terms, acronyms, abbreviations, and idiosyncratic phrasing (`he presented with elevated systolic pressure...').") :- x_cid(a65b1273c27aa9).
xc_microtheory(a65b1273c27aa9,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aa9,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aa9,1651).
xc_kb_names(a65b1273c27aa9,[]).
xc_mapping_rows(a65b1273c27aa9,[]).
x_comment('x_InvestmentMarketLanguage-Register',"This is the style of discourse conventionally associated with stock and bond trading. It is characterized by anthropomorphizing of inanimate things: `gold suffered today but tech stocks rebounded...'.") :- x_cid(a65b1273c27aaa).
xc_microtheory(a65b1273c27aaa,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aaa,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aaa,1652).
xc_kb_names(a65b1273c27aaa,[]).
xc_mapping_rows(a65b1273c27aaa,[]).
x_comment('x_LinguisticsLanguage-Register',"This is the style of discourse conventionally associated with linguistics. It is characterized by a preference for certain imperatives (`consider', `recall', `observe'), large numbers of example sentences, and the use of acronyms.") :- x_cid(a65b1273c27aab).
xc_microtheory(a65b1273c27aab,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aab,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aab,1653).
xc_kb_names(a65b1273c27aab,[]).
xc_mapping_rows(a65b1273c27aab,[]).
x_comment('x_PornographyLanguage-Register',"This is the style of discourse conventionally associated with the marketing of pornographic materials as well as certain of those materials, such as movies in which there is dialog. It is characterized by the use of vulgar terminology and a very narrow universe of discourse in which persons appear to be little more than subjects and objects of sexual gratification.\n\nUse of certain terms, such as \"femdom\" and \"facial\", are mostly specific to this register.") :- x_cid(a65b1273c27aac).
xc_microtheory(a65b1273c27aac,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aac,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aac,1654).
xc_kb_names(a65b1273c27aac,[]).
xc_mapping_rows(a65b1273c27aac,[]).
x_comment('x_PsychologyPublicationLanguage-Register',"This is an example of a #$LinguisticRegister which is explicitly set out and, at least in principle, enforced. The APA Publication Manual specifies that psychological writing should be clear and maximally informative, writers should use short sentences, the active voice of verbs, and eschew metaphors and figurative writing.") :- x_cid(a65b1273c27aad).
xc_microtheory(a65b1273c27aad,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aad,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aad,1657).
xc_kb_names(a65b1273c27aad,[]).
xc_mapping_rows(a65b1273c27aad,[]).
x_comment('x_ComputerLanguage-Register',"This is the style of discourse conventionally associated with the computer world. It is characterized by the use of idiomatic expressions (`hacker'), idiosyncratic syntax (use of the letter `z' for pluralization), and a range of jargon specific to computers and the internet.") :- x_cid(a65b1273c27aae).
xc_microtheory(a65b1273c27aae,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aae,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aae,1658).
xc_kb_names(a65b1273c27aae,[]).
xc_mapping_rows(a65b1273c27aae,[]).
x_comment('x_ExternalCauseState-VerbClass',"This verb class includes those change of state verbs that\n\nrelate to externally caused changes of state (section 45.4 of Levin\n\ntext). These verbs participate in the causative/inchoative\n\nalternation\nchange of state verbs see #$Break-VerbClass, #$Bend-VerbClass,\n\n#$Cooking-VerbClass, #$EntitySpecificChangeOfState-VerbClass,\n\n#$MeasurableChangeOfState-VerbClass, #$Lodge-VerbClass.") :- x_cid(a65b1273c27aaf).
xc_microtheory(a65b1273c27aaf,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aaf,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aaf,1659).
xc_kb_names(a65b1273c27aaf,[]).
xc_mapping_rows(a65b1273c27aaf,[]).
x_comment(x_ObliqueSubjectAlternationType,"Each instance of this collection is a type of alternation which does not involve a change in the transitivity of the verb but which does involve a change in the number of NPs the verb is involved with.  Example: 'NP1 V NP2 [PP NP3]' structure may alternate with 'NP3 V NP2'.") :- x_cid(a65b1273c27ab0).
xc_microtheory(a65b1273c27ab0,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ab0,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ab0,1671).
xc_kb_names(a65b1273c27ab0,[]).
xc_mapping_rows(a65b1273c27ab0,[]).
x_comment(x_InstrumentSubjectAlternation,"The alternation between the structure 'NP1 V NP2 \"with\" NP3' and the structure 'NP3 V NP2.'  Note that not all instruments can participate in this alternation. In particular, only \"intermediary\" instruments -- ones that can appear as subjects -- can be used.  Example: Fred dried the clothes with the hairdryer. / The hairdryer dried the clothes.") :- x_cid(a65b1273c27ab1).
xc_microtheory(a65b1273c27ab1,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ab1,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ab1,1672).
xc_kb_names(a65b1273c27ab1,[]).
xc_mapping_rows(a65b1273c27ab1,[]).
x_comment(x_BenefactiveAlternation,"The alternation between the structure 'NP1 V NP2 \"for\" NP3' and the structure 'NP1 V NP3 NP2.'  Verbs typically taking this alternation are verbs of obtaining and verbs of creation.\n\nExample: Sally built the treehouse for Fred. / Sally built Fred a treehouse.") :- x_cid(a65b1273c27ab2).
xc_microtheory(a65b1273c27ab2,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ab2,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ab2,1673).
xc_kb_names(a65b1273c27ab2,[]).
xc_mapping_rows(a65b1273c27ab2,[]).
x_comment('x_Crane-VerbClass',"This verb class (see 40.3.2 in the Levin text) includes verbs which describe gestures made with specific body parts; the subject of the verb is the possessor of the body part in the direct object position. The object must be explicitly expressed. Example: Fred rolled his eyes. Sally shook her fist at the insolent youth.") :- x_cid(a65b1273c27ab3).
xc_microtheory(a65b1273c27ab3,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ab3,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ab3,1676).
xc_kb_names(a65b1273c27ab3,[]).
xc_mapping_rows(a65b1273c27ab3,[]).
x_comment('x_Get-VerbClass',"This verb class (see 13.5.1 in the Levin text) includes verbs of obtaining that can take the #$BenefactiveAlternation.  Note that many of these verbs also belong to the #$Steal-VerbClass. Example: Sally rents her apartment from Fred.  Fred leases his car from Sally.") :- x_cid(a65b1273c27ab4).
xc_microtheory(a65b1273c27ab4,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ab4,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ab4,1677).
xc_kb_names(a65b1273c27ab4,[]).
xc_mapping_rows(a65b1273c27ab4,[]).
x_comment('x_Characterize-VerbClass',"This verb class (see 29.2 in the Levin text) includes verbs that are typically used to describe properties of entities.   All of these verbs take predicative complements and these typically apply to the postverbal NP. The most common frame for these verbs is 'NP V NP as NP.'") :- x_cid(a65b1273c27ab5).
xc_microtheory(a65b1273c27ab5,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ab5,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ab5,1678).
xc_kb_names(a65b1273c27ab5,[]).
xc_mapping_rows(a65b1273c27ab5,[]).
x_comment(x_verbClassSemTrans,"This predicate expresses a semantic translation template for verbs in virtue of their membership in a verb class.  (#$verbClassSemTrans VERBCLASS FRAME TEMPLATE) means that for any VERB SENSE that is a member of VERBCLASS (#$hasVerbAsMember VERBCLASS VERB SENSE), the following is true of it: (#$verbSemTrans VERB SENSE FRAME TEMPLATE).") :- x_cid(a65b1273c27ab6).
xc_microtheory(a65b1273c27ab6,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ab6,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ab6,1679).
xc_kb_names(a65b1273c27ab6,[]).
xc_mapping_rows(a65b1273c27ab6,[]).
x_comment(x_verbClassFrame,"This predicate allows representation of the subcategorization frames taken by instances of a verb class. (#$verbClassFrame VERBCLASS FRAME) means that for any VERB SENSE that is a member of VERBCLASS (#$hasVerbAsMember VERBCLASS VERB SENSE), the following is true of it: (#$subcatFrame VERB #$Verb SENSE FRAME).") :- x_cid(a65b1273c27ab7).
xc_microtheory(a65b1273c27ab7,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ab7,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ab7,1680).
xc_kb_names(a65b1273c27ab7,[]).
xc_mapping_rows(a65b1273c27ab7,[]).
x_comment(x_verbClassAlternation,"This predicate allows representations of the alternations taken by instances of a verb class. (#$verbClassFrame VERBCLASS ALTERNATION) means that for any VERB SENSE that is a member of VERBCLASS (#$hasVerbAsMember VERBCLASS VERB SENSE), the following is true of it: (#$participatesInAlternation VERB SENSE ALTERNATION).") :- x_cid(a65b1273c27ab8).
xc_microtheory(a65b1273c27ab8,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ab8,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ab8,1681).
xc_kb_names(a65b1273c27ab8,[]).
xc_mapping_rows(a65b1273c27ab8,[]).
x_comment(x_Alternation,"The set of alternations found in natural languages.") :- x_cid(a65b1273c27ab9).
xc_microtheory(a65b1273c27ab9,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ab9,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ab9,1682).
xc_kb_names(a65b1273c27ab9,[]).
xc_mapping_rows(a65b1273c27ab9,[]).
x_comment(x_alternationSubcatFrames,"This predicate allows representations of the #$subcatFrames that a verb can alternate between. (#$alternationSubcatFrames ALTERNATION SUBCAT1 SUBCAT2) means that for VERB participating in ALTERNATION, given that the arguments remain the same, the #$verbSemTrans that has VERB and SUBCAT1 as an arg. and the #$verbSemTrans that has VERB and SUBCAT2 as an arg. are semantically equivalent.") :- x_cid(a65b1273c27aba).
xc_microtheory(a65b1273c27aba,x_GeneralLexiconMt).
xc_source_file(a65b1273c27aba,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27aba,1683).
xc_kb_names(a65b1273c27aba,[]).
xc_mapping_rows(a65b1273c27aba,[]).
x_comment('x_ContiguousLocation-VerbClass',"This verb class (see 47.8 in the Levin text) \n\nconsists of verbs used to describe a contiguous spatial\n\nrelation between two things.  Though some verbs\n\n in this class, e.g., #$Touch-TheWord, \n\n describe a symmetric relationship, most inflict a clear\n\n subject-first, object-next interpretation\n\n of their relata, as does #$Straddle-TheWord, in\n\n '<SUBJ> straddles <OBJ>.'\n\n  These verbs require a 'by <SUBJ>' phrase when\n\n used in the passive.  It is not the case that every member of\n\n this verb class participates in an alternation, though\n\n   some participate in #$UnderstoodReciprocalObjectAlternation.") :- x_cid(a65b1273c27abb).
xc_microtheory(a65b1273c27abb,x_GeneralLexiconMt).
xc_source_file(a65b1273c27abb,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27abb,1684).
xc_kb_names(a65b1273c27abb,[]).
xc_mapping_rows(a65b1273c27abb,[]).
x_comment(x_UnderstoodReciprocalObjectAlternation,"The alternation between the structures\n\n 'NP1 V NP2' in the transitive \n\n and 'NP1 \"and\" NP2 V' in the \n\n intransitive.  In certain cases,\n\n'NP1 \"and\" NP2 V \"each other\"' is \n\npossible.  The participants in the action described must\n\n be of comparable status.  Thus, 'The drunk\n\n  hugged the lamppost' *NOT 'The drunk and the\n\n lamppost hugged,' but 'The drunk hugged his\n\n friend' AND 'The drunk and his friend \n\nhugged.'") :- x_cid(a65b1273c27abc).
xc_microtheory(a65b1273c27abc,x_GeneralLexiconMt).
xc_source_file(a65b1273c27abc,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27abc,1707).
xc_kb_names(a65b1273c27abc,[]).
xc_mapping_rows(a65b1273c27abc,[]).
x_comment('x_Amuse-VerbClass',"The verbs in this class are all verbs of psychological state (section 31 of Levin text).  They are transitive, and take as object the experiencer of the psychological state.  For some of these verbs, the experiencer or stimulus of the emotion may be explicit or understood.  For example, \"He amused me\", \"I was amused\", \"That joke never fails to amuse.\"") :- x_cid(a65b1273c27abd).
xc_microtheory(a65b1273c27abd,x_GeneralLexiconMt).
xc_source_file(a65b1273c27abd,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27abd,1728).
xc_kb_names(a65b1273c27abd,[]).
xc_mapping_rows(a65b1273c27abd,[]).
x_comment(x_webSearchableStrings,"(#$webSearchableStrings FORT STRING)   says 1) it is plausible that a web-searcher    who is interested in the concept  represented by FORT will search for that  information using STRING, and   2) STRING is generally *not* recognized as   a legitimate English construction -- i.e.,   it is not a construction that we eventually want    represented in the Cyc Lexicon.  Because of  1), Cyc will 'understand' FORT as a possible   disambiguation for STRING.  Because of 2),  Cyc will never offer STRING in generating  English for FORT; accordingly, any assertion  using #$webSearchableStrings must be made   in #$WebSearchLexicalMt.") :- x_cid(a65b1273c27abe).
xc_microtheory(a65b1273c27abe,x_GeneralLexiconMt).
xc_source_file(a65b1273c27abe,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27abe,1729).
xc_kb_names(a65b1273c27abe,[]).
xc_mapping_rows(a65b1273c27abe,[]).
x_comment(x_prepSemTrans,"(prepSemTrans PREP INT FRAME TRANS) means that the translation of word sense number INT of PREP in frame FRAME is TRANS.") :- x_cid(a65b1273c27abf).
xc_microtheory(a65b1273c27abf,x_GeneralLexiconMt).
xc_source_file(a65b1273c27abf,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27abf,1730).
xc_kb_names(a65b1273c27abf,[]).
xc_mapping_rows(a65b1273c27abf,[]).
x_comment(x_NounCompoundRule,"The collection of all rules used by the #$NounPhraseParser.") :- x_cid(a65b1273c27ac0).
xc_microtheory(a65b1273c27ac0,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ac0,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ac0,1731).
xc_kb_names(a65b1273c27ac0,[]).
xc_mapping_rows(a65b1273c27ac0,[]).
x_comment(x_NounCompoundRuleIndexicalTerm,"The collection of indexical terms that can appear in noun-compound rule constraints and semantic specifications (cf. #$ncRuleTemplate), and whose denotation depends on the compound being parsed.") :- x_cid(a65b1273c27ac1).
xc_microtheory(a65b1273c27ac1,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ac1,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ac1,1732).
xc_kb_names(a65b1273c27ac1,[]).
xc_mapping_rows(a65b1273c27ac1,[]).
x_comment(x_TheNCHead,"#$TheNCHead is a special kind of term whose only purpose is to be used in #$ELSentence-Assertibles that appear as the second argument of an #$ncRuleConstraint. For example, the assertion (#$ncRuleConstraint #$PeopleWatching-NCR (#$equals #$TheNCHead #$WatchingSomething))  means that one of the conditions on the application of the #$NounCompoundRule #$PeopleWatching-NCR is that the meaning of the head part of the compound be equal to #$WatchingSomething.") :- x_cid(a65b1273c27ac2).
xc_microtheory(a65b1273c27ac2,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ac2,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ac2,1733).
xc_kb_names(a65b1273c27ac2,[]).
xc_mapping_rows(a65b1273c27ac2,[]).
x_comment(x_TheNCModifier,"#$TheNCModifier is a special kind of term whose only purpose is to be\n\nused in #$ELSentence-Assertibles that appear as the second argument of an #$ncRuleConstraint.\n\nFor example, the assertion (#$ncRuleConstraint #$ArtExpert-NCR (#$NCPOSConstraintFn #$TheNCModifier #$Noun)) \n\nmeans that one of the conditions on the application of the #$NounCompoundRule #$ArtExpert-NCR is that\n\nthe modifier part of the compound be a noun.") :- x_cid(a65b1273c27ac3).
xc_microtheory(a65b1273c27ac3,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ac3,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ac3,1734).
xc_kb_names(a65b1273c27ac3,[]).
xc_mapping_rows(a65b1273c27ac3,[]).
x_comment(x_ncMorphologyRequirement,"The predicate exists so as to be able to express part of speech constraints for \ninstances of #$NounCompoundRule in such a way that they can be checked for well-formedness\nby the wff-checker. See #$ncPOSRequirement.") :- x_cid(a65b1273c27ac4).
xc_microtheory(a65b1273c27ac4,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ac4,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ac4,1743).
xc_kb_names(a65b1273c27ac4,[]).
xc_mapping_rows(a65b1273c27ac4,[]).
x_comment(x_ncRuleLabel,"The assertion (#$ncRuleLabel RULE STRING) means that STRING is a complex nominal \nexpression that is a good example of the kind of nominal expressions designed to be handled\nby the #$NounCompoundRule RULE.") :- x_cid(a65b1273c27ac5).
xc_microtheory(a65b1273c27ac5,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ac5,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ac5,1746).
xc_kb_names(a65b1273c27ac5,[]).
xc_mapping_rows(a65b1273c27ac5,[]).
x_comment(x_ncRuleConstraint,"This predicate is used to record constraints imposed by instances of #$NounCompoundRule.\n\nFor example, the assertion (#$ncRuleConstraint #$ArtExpert-NCR (#$NCPOSConstraintFn #$TheNCModifier #$Noun)) \n\nmeans that one of the conditions on the application of the #$NounCompoundRule #$ArtExpert-NCR \n\nis that the part of speech of the modifier part of the compound be #$Noun.") :- x_cid(a65b1273c27ac6).
xc_microtheory(a65b1273c27ac6,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ac6,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ac6,1749).
xc_kb_names(a65b1273c27ac6,[]).
xc_mapping_rows(a65b1273c27ac6,[]).
x_comment(x_ncRuleTemplate,"This predicate is used to record the fact that if two (sequences of) words \n\nsatisfy all the constraint of a #$NounCompoundRule then some of the possible meanings of\n\nthe compound represented by their concatenation can be obtained by substituting in for #$TheNCHead\n\nthe meanings of the head (sequence of) word(s) that are consistent with the constraints of the \n\n#$NounCompoundRule, and similarly for #$TheNCModifier.") :- x_cid(a65b1273c27ac7).
xc_microtheory(a65b1273c27ac7,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ac7,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27ac7,1756).
