x_comment(x_NCPOSConstraintFn,"When a NAT of the form (#$NCPOSConstraintFn COMPONENT POS) appears as the\n\nsecond argument of a #$ncRuleConstraint assertion, this means that the #$NounCompoundRule \n\nwhich is the first argument of that assertion applies only if COMPONENT can be proved to \n\nhave Part Of Speech POS.") :- x_cid(a65b1273c27ad5).
xc_microtheory(a65b1273c27ad5,x_GeneralLexiconMt).
