x_comment(x_NCPOSPredConstraintFn,"When a NAT of the form (#$NCPOSPredConstraintFn COMPONENT POS-PRED) appears as the\n\nsecond argument of a #$ncRuleConstraint assertion, this means that the #$NounCompoundRule \n\nwhich is the first argument of that assertion applies only if COMPONENT can be proved to \n\nhave Part Of Speech predicate POS-PRED.") :- x_cid(a65b1273c27ad6).
xc_microtheory(a65b1273c27ad6,x_GeneralLexiconMt).
