x_comment(x_NCGenlsConstraintFn,"When a NAT of the form (#$NCGenlsConstraintFn SMALL BIG) appears as the second argument of a #$ncRuleConstraint assertion, this means that the #$NounCompoundRule which is the first argument of that assertion applies only if SMALL can be proved to be a subclass of BIG in an appropriate microtheory. Which microtheories are appropriate is established as one of the parameters of the #$NounPhraseParser.") :- x_cid(a65b1273c27ad8).
xc_microtheory(a65b1273c27ad8,x_GeneralLexiconMt).
