x_comment(x_NCIsaConstraintFn,"When a NAT of the form (NCIsaConstraintFn SMALL BIG) appears as the second argument of a #$ncRuleConstraint assertion, this means that the #$NounCompoundRule  which is the first argument of that assertion applies only if SMALL can be proved to be  a instance of BIG in an appropriate microtheory. Which microtheories are appropriate is established as one of the parameters of the #$NounPhraseParser.") :- x_cid(a65b1273c27ad9).
