x_comment('x_denotation-Prep',"Use this predicate to indicate the group of relations that should be used when representing assertions involving the preposition in question. Example: (#$denotation-Prep #$In-TheWord #$Preposition-Locative #$in-UnderspecifiedContainer) means that sentences using the locative \"in\" should use #$in-UnderspecifiedContainer or one of its specpreds in representation. The corresponding #$prepSemTrans assertions will provide an exact specification of how such relations should be used. For example, (#$prepSemTrans #$In-TheWord 4 #$VerbPhraseModifyingFrame (#$objectFoundInLocation :MOD-OBJ :OBJECT)) and (#$prepSemTrans #$In-TheWord 1 #$VerbPhraseModifyingFrame (#$eventOccursAt :ACTION :OBJECT))") :- x_cid(a65b1273c27ada).
xc_microtheory(a65b1273c27ada,x_GeneralLexiconMt).
xc_source_file(a65b1273c27ada,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
