xc_mapping_rows(a65b1273c27ada,[]).
x_comment('x_prepSemTrans-New',"(#$prepSemTrans-New WORD PREP FRAME TRANS) means that the translation of the preposition WORD of type PREP in frame FRAME is TRANS. Example: (#$prepSemTrans-New #$In-TheWord #$Preposition-Locative #$VerbPhraseModifyingFrame (#$eventOccursAt :ACTION :IND-OBJECT)).") :- x_cid(a65b1273c27adb).
xc_microtheory(a65b1273c27adb,x_GeneralLexiconMt).
