x_comment(x_NLNumberFn,"(#$NLNumberFn TAG TERM) means that TERM appeared in a natural language utterance with the linguistic/morphological number denoted by TAG.  For example, (#$NLTagFn #$Singular-NLAttr #$Dog) would mean that some word meaning #$Dog occurred in the singular.  This function serves as a hint to the NL subsystems that this term was used with a particular number, and is only intended to serve as a stand-in until the NL subsystems can determine the correct form of TERM to use in the semantic translation of the utterance.  Note that uses of this can (and frequently should) be nested.  For instance, \"some cats\" would return from the parser as (#$NLTagFn #$Some-NLAttr (#$NLTagFn #$Plural-NLAttr #$Cat)).") :- x_cid(a65b1273c27adc).
xc_microtheory(a65b1273c27adc,x_GeneralLexiconMt).
xc_source_file(a65b1273c27adc,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27adc,1834).
xc_kb_names(a65b1273c27adc,[]).
xc_mapping_rows(a65b1273c27adc,[]).
x_comment(x_NLSemFn,"(#$NLSemFn TAG TERM) means that TERM appeared in a natural language utterance with the intent of referring to the TAG form of TERM.  For example, (#$NLSemFn #$RelevantInstance-NLAttr #$Dog) would mean that some word meaning #$Dog occurred, but was intended to refer to a specific instance of #$Dog, rather than to the collection.  This function serves as a hint to the NL subsystems, and is only intended to serve as a stand-in until the NL subsystems can determine the correct form of TERM to use in the semantic translation of the utterance.") :- x_cid(a65b1273c27add).
xc_microtheory(a65b1273c27add,x_GeneralLexiconMt).
xc_source_file(a65b1273c27add,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
