x_comment(x_subcatFrameArity,"(#$subcatFrameArity FRAME NUM) indicates that a phrase headed by #$SubcategorizationFrame FRAME has NUM dependents.  Each dependent of a phrase headed by a given FRAME should be defined by at least one #$subcatFrameDependentConstraints assertion.  In other words, for any given FRAME, if (#$subcatFrameArity FRAME NUM) is true, then there should be at least NUM #$subcatFrameDependentConstraints assertions with FRAME as their arg1.") :- x_cid(a65b1273c27b0e).
xc_microtheory(a65b1273c27b0e,x_GeneralLexiconMt).
