x_comment(x_subcatFrameDependentConstraint,"(#$subcatFrameDependentConstraint FRAME NUM CONSTRAINT) indicates that CONSTRAINT is the #$PhraseStructureConstraint for the NUM-th dependent in phrases headed by #$SubcategorizationFrame FRAME.  Each dependent of a phrase headed by a given FRAME should be defined by at least one #$subcatFrameDependentConstraint assertion.  In other words, for any given FRAME, if (#$subcatFrameArity FRAME NUM) is true, then there should be at least NUM #$subcatFrameDependentConstraint assertions with FRAME as their arg1.") :- x_cid(a65b1273c27b0f).
xc_microtheory(a65b1273c27b0f,x_GeneralLexiconMt).
