x_comment(x_NLWordForm,"The collection of abstract, yet fully-specified (for morphological composition, part of speech, agreement features, meaning, and phonology, but not necessarily spelling) natural language word forms. An #$NLWordForm may be morphologically atomic or complex - i.e. it may be analyzeable into one or more morphemes. From a syntactic point of view, it is an atom - i.e., the syntactic combination of an #$NLWordForm with something else is no longer an #$NLWordForm. Each #$NLWordForm can be instantiated (via #$instantiationOfAIS) by arbitrarily many spoken or written #$NLWord-IBTs, and each is associated (via #$lexemeOfWordForm) with a single #$LexicalWord. An #$NLWordForm is defined entirely by the values of its linguistic features; two #$NLWordForms with the same feature values are identical. Thus the #$NLWordForms instantiated by \"hit\" in \"The arrow hit the target\" and \"The arrow has hit the target\" are distinct, because the first one has simple past tense while the second one has perfect tense. But those instantiated by \"hit\" in \"The arrow hit the target\" and \"The arrow hit the tree\" would be the same under a typical linguistic analysis.") :- x_cid(a65b1273c27b11).
xc_microtheory(a65b1273c27b11,x_GeneralLexiconMt).
xc_source_file(a65b1273c27b11,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27b11,1905).
xc_kb_names(a65b1273c27b11,[]).
xc_mapping_rows(a65b1273c27b11,[]).
x_comment(x_posPredOfConstituent,"(#$posPredOfConstituent CONST PRED) means that the part-of-speech predicate of CONST is PRED. For example, the part-of-speech predicate for \"house\" and \"the house that Jack built\" would both be (some specialization of) #$singular.") :- x_cid(a65b1273c27b12).
xc_microtheory(a65b1273c27b12,x_GeneralLexiconMt).
xc_source_file(a65b1273c27b12,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27b12,1906).
xc_kb_names(a65b1273c27b12,[]).
xc_mapping_rows(a65b1273c27b12,[]).
x_comment(x_lexemeOfWordForm,"(#$lexemeOfWordForm WORD-FORM LEXEME) means that the word WORD-FORM belongs to the lexeme LEXEME.") :- x_cid(a65b1273c27b13).
xc_microtheory(a65b1273c27b13,x_GeneralLexiconMt).
xc_source_file(a65b1273c27b13,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27b13,1907).
xc_kb_names(a65b1273c27b13,[]).
xc_mapping_rows(a65b1273c27b13,[]).
x_comment('x_NLWord-IBT',"The collection of all spoken, written, or otherwise expressed word tokens recognizeable as instantiations (see #$instantiationOfAIS) of #$NLWordForms. Note that a single #$NLWord-IBT can instantiate several #$NLWordForms.  Puns are examples of such multiple instantiations.") :- x_cid(a65b1273c27b14).
xc_microtheory(a65b1273c27b14,x_GeneralLexiconMt).
xc_source_file(a65b1273c27b14,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27b14,1908).
xc_kb_names(a65b1273c27b14,[]).
xc_mapping_rows(a65b1273c27b14,[]).
x_comment(x_possiblePOSOfWordIBT,"A binary predicate which relates instances of #$NLWord-IBT to instances of #$SpeechPart. (#$possiblePOSOfWordIBT WORD-IBT POS) means that POS is one of the parts of speech that WORD-IBT could have. Note that there is not necessarily a unique part of speech for an #$NLWord-IBT, since it may instantiate more than one #$NLWordForm, corresponding to different parts of speech. For example, an instantiation of the character string \"hit\" may be either a #$Noun or a #$Verb.") :- x_cid(a65b1273c27b15).
xc_microtheory(a65b1273c27b15,x_GeneralLexiconMt).
xc_source_file(a65b1273c27b15,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27b15,1909).
xc_kb_names(a65b1273c27b15,[]).
xc_mapping_rows(a65b1273c27b15,[]).
x_comment('x_NLWord-Phonological',"The collection of all #$AbstractInformationStructures that represent the phonology of a natural language word. Every instantiation of a given #$NLWord-Phonological will be an instance of #$NLWord-IBT, and will share the same phonology, but may differ somewhat in spelling, due to the arbitrariness of spelling conventions and the possibility that the writer may be ignorant of or may choose not to follow such conventions, or in pronunciation, due to factors such as an individual's accent or the phonological environment in which the word is pronounced.") :- x_cid(a65b1273c27b16).
xc_microtheory(a65b1273c27b16,x_GeneralLexiconMt).
xc_source_file(a65b1273c27b16,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27b16,1910).
xc_kb_names(a65b1273c27b16,[]).
xc_mapping_rows(a65b1273c27b16,[]).
