x_comment(x_psRuleTemplateDtr,"(#$psRuleTemplateDtr RULE N) means that the semantics of any phrase described by the #$PhraseStructureRule RULE is determined by substituting the semantics of the other daughters into the semantic template for the Nth daughter.") :- x_cid(a65b1273c27b19).
