x_comment(x_untensed,"This predicate is a generalization over the #$SpeechPartPredicates for all untensed verb forms.  This predicate is #$notAssertible in English, since it will always cash out as an assertion on one of its spec-preds.") :- x_cid(a65b1273c27b1c).
xc_microtheory(a65b1273c27b1c,x_GeneralLexiconMt).
