x_comment(x_SubjectRolePredicate,"The collection of \n\n#$TemplateMarkerObjects that are used\n\n in representing whether #$TheSentenceSubject of a given\n\n sentence plays an active or passive role.") :- x_cid(a65b1273c27b1d).
