x_comment('x_causes-Underspecified',"A generalization of\n\nall individual-level causes-* predicates. \n\n(#$causes-Underspecified CAUSE EFFECT) says that CAUSE \n\ncauses EFFECT.  Whenever possible, use one\n\n of the spec preds or axiomatically-related specializations.  See #$NoteAboutCausalityPredicates for a map of related predicates.") :- x_cid(a65b1273c27b1e).
xc_microtheory(a65b1273c27b1e,x_GeneralLexiconMt).
xc_source_file(a65b1273c27b1e,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
