xc_mapping_rows(a65b1273c27b1e,[]).
x_comment(x_indirectObjectRoles,"(#$indirectObjectRoles EVENT-TYPE ROLE) means that an indirect object of a verb \n\nthat denotes EVENT-TYPE may be assumed to denote an actor that plays ROLE in the event \n\ndenoted by the verb.") :- x_cid(a65b1273c27b1f).
xc_microtheory(a65b1273c27b1f,x_GeneralLexiconMt).
