xc_mapping_rows(a65b1273c27b1f,[]).
x_comment(x_preferredIndirectObjectRole,"(#$preferredIndirectObjectRole EVENT-TYPE ROLE) means that ROLE best describes\n\nthe role played by the referent of an indirect object of a verb that denotes EVENT-TYPE.") :- x_cid(a65b1273c27b20).
xc_microtheory(a65b1273c27b20,x_GeneralLexiconMt).
xc_source_file(a65b1273c27b20,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
