x_comment(x_ConcatenatePhrasesFn,"(#$ConcatenatePhrasesFn PHRASE1 ... PHRASEN) denotes the natural-language phrase formed by concatenating PHRASE1 ... PHRASEN.") :- x_cid(a65b1273c27b21).
xc_microtheory(a65b1273c27b21,x_GeneralLexiconMt).
xc_source_file(a65b1273c27b21,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
