x_comment(x_BestNLPhraseOfStringFn,"(#$BestNLPhraseOfStringFn STRING) denotes the\n(possibly contextually dependent) best natural-language word\nor phrase partially specified by STRING. The exact identity\nof the phrase, including its syntactic structure, etc., will\noften not need to be known, if the phrase is just\nintended to be represented or expressed as a\n#$CharacterString.") :- x_cid(a65b1273c27b22).
xc_microtheory(a65b1273c27b22,x_GeneralLexiconMt).
xc_source_file(a65b1273c27b22,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
