xc_mapping_rows(a65b1273c27b22,[]).
x_comment(x_BestNLWordFormOfLexemeFn,"(#$BestNLWordFormOfLexemeFn LEXEME) denotes the\n(contextually dependent) natural-language word that best\ninstantiates LEXEME. The exact identity of the word form,\nincluding its morphological form, agreement features, etc.,\nmay not need to be known, especially if it is just intended\nto be represented or expressed as a #$CharacterString.") :- x_cid(a65b1273c27b23).
xc_microtheory(a65b1273c27b23,x_GeneralLexiconMt).
xc_source_file(a65b1273c27b23,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27b23,1961).
xc_kb_names(a65b1273c27b23,[]).
xc_mapping_rows(a65b1273c27b23,[]).
x_comment(x_PhraseFormFn,"(#$PhraseFormFn CONSTRAINT PHRASE) denotes the\n(typically contextually dependent) natural language word or\nphrase PHRASE, while specifying a linguistic constraint on\nits form. Namely, the linguistic context requires that PHRASE\nmeet CONSTRAINT. For instance, in a typical English-language\ncontext, (#$PhraseFormFn #$singular-Generic\n(#$TermParaphraseFn #$Dog)) would denote the\n#$SententialConstituent instantiated by the string 'dog'.") :- x_cid(a65b1273c27b24).
xc_microtheory(a65b1273c27b24,x_GeneralLexiconMt).
xc_source_file(a65b1273c27b24,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27b24,1967).
xc_kb_names(a65b1273c27b24,[]).
xc_mapping_rows(a65b1273c27b24,[]).
x_comment(x_BestDetNbarFn,"(#$BestDetNbarFn DET NBAR) denotes the (possibly contextually dependent) best noun phrase consisting of NBAR with determiner DET. For instance, (#$BestDetNbarFn (#$BestNLWordFormOfLexemeFn #$The-TheWord) (#$PhraseFormFn #$singular-Generic (#$TermParaphraseFn #$Dog))) would denote the #$NLPhrase instantiated by the string 'the dog' in a typical English-language context.") :- x_cid(a65b1273c27b25).
xc_microtheory(a65b1273c27b25,x_GeneralLexiconMt).
xc_source_file(a65b1273c27b25,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27b25,1975).
xc_kb_names(a65b1273c27b25,[]).
xc_mapping_rows(a65b1273c27b25,[]).
x_comment(x_BestVerbFormForSubjectFn,"(#$BestVerbFormForSubjectFn VERB-LEXEME PHRASE)\ndenotes the (possibly contextually dependent) best finite\nverb form of VERB-LEXEME, given that it is constrained to\nagree with PHRASE as its subject. For instance,\n(#$BestVerbFormForSubjectFn #$Eat-TheWord (#$PhraseFormFn\n#$singular-Generic (#$TermParaphraseFn #$Dog))) would denote\n'eats' in a present-tense, typical English-language\ncontext.") :- x_cid(a65b1273c27b26).
xc_microtheory(a65b1273c27b26,x_GeneralLexiconMt).
xc_source_file(a65b1273c27b26,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27b26,1976).
