xc_mapping_rows(a65b1273c27b26,[]).
x_comment(x_speechPartOfWordForm,"(speechPartOfWordForm WORD-FORM POS) means that WORD-FORM\nhas the #$SpeechPart POS.") :- x_cid(a65b1273c27b27).
