x_comment(x_posOfPhraseType,"(#$posOfPhraseType PHRASE-TYPE POS) indicates that the syntactic category of every instance of PHRASE-TYPE is POS. For example, (#$posOfPhraseType #$NounPhrase #$Noun).") :- x_cid(a65b1273c27b2a).
xc_microtheory(a65b1273c27b2a,x_GeneralLexiconMt).
