x_comment(x_TheVPParse,"#$TheVPParse is an #$IntermediateVocabFunction that is used to organize Verb Phrase Parser output in a form where it can be reformulated into assertible CycL. (#$TheVPParse SIT ROLE) denotes that #$IntermediateVocabTerm that can be processed by the #$CycLReformulator in the way prescribed by the relevant #$reformulatorEquiv and #$reformulatorEquals assertions. #$TheVPParse NAUTs are generated automatically by the #$CycPhraseStructureParser.") :- x_cid(a65b1273c27b2b).
xc_microtheory(a65b1273c27b2b,x_GeneralLexiconMt).
