x_comment(x_NLResponseFn,"#$NLResponseFn is used to specify a response from a user to Cyc with a specific attribute.  For example, if Cyc asks a user a question and the user doesn't know the answer, the response from the user will be (#$NLResponseFn #$Ignorance-NLResponse).  This will be the CycL representation for any of the myriad ways in which a user might signal ignorance of the answer to a question posed by Cyc.") :- x_cid(a65b1273c27b2d).
xc_microtheory(a65b1273c27b2d,x_GeneralLexiconMt).
