x_comment(x_NLRequestFn,"NATs using NLRequestFn represent requests by a user to do something with an #$RKFTool.  The arg3 of #$NLRequestFn is the list of arguments to be sent to the tool, and will frequently be nil.  (#$NLRequestFn #$StartTool-NLRequest #$CycConceptCreator (\"anthrax\")) signifies a request to start the #$CycConceptCreator with the argument list (\"anthrax\").") :- x_cid(a65b1273c27b34).
