x_comment('x_StartTool-NLRequest',"#$StartTool-NLRequest is an attribute of a request from a user that signifies that the request is a request for the system to start a particular RKF tool.  For example, a request to start the #$CycScenarioDescriber would be represented in CycL by (#$NLRequestFn #$StartTool-NLRequest #$CycConceptCreator (\"anthrax\")).") :- x_cid(a65b1273c27b35).
