x_comment('x_AbortTool-NLRequest',"#$AbortTool-NLRequest is an attribute of a request from a user that signifies that the request is a request for the system to terminate a particular RKF tool.  For example, a request to terminate the #$CycConceptCreator being used to create \"anthrax\" would be represented in CycL by (#$NLRequestFn #$StartTool-NLRequest #$CycConceptCreator (\"anthrax\")).") :- x_cid(a65b1273c27b36).
