x_comment(x_NLRolePredicate,"A collection of relationships. Each instance of #$NLRolePredicate represents a syntactic relation that can hold between a type of situation and a #$Role involved in it. #$subjectRoles, for example, relates a situation-type to the role which typically is played by the subject of a sentence using a verb to express that situation. Example: (#$subjectRoles #$EatingEvent #$performedBy)") :- x_cid(a65b1273c27b37).
xc_microtheory(a65b1273c27b37,x_GeneralLexiconMt).
