x_comment(x_RelationalNounSlot,"The collection of binary predicates that describe a specified relation of an animal, group of animals (usually human animals), or an organization to another animal (also usually a human animal).  These relations can be summed up by common nouns such as 'mother' or 'boss' or 'neighbor'.  This class of predicates exists to facilitate parsing of sentences with forms such as 'X has a Y' or 'does X have a Y?' where Y is one of these relational nouns.") :- x_cid(a65b1273c27b5b).
xc_microtheory(a65b1273c27b5b,x_GeneralLexiconMt).
xc_source_file(a65b1273c27b5b,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27b5b,2069).
xc_kb_names(a65b1273c27b5b,[]).
xc_mapping_rows(a65b1273c27b5b,[]).
x_comment('x_denotationRelatedTo-New',"The predicate #$denotationRelatedTo-New is used to link English words with concepts indirectly related to their meanings.  For instance, both #$Wife-TheWord and #$Husband-TheWord are semantically connected to the predicate #$wife, but the two words do not denote the same relation.  If (#$denotationRelatedTo-New #$Husband-TheWord #$CountNoun 0 #$wife), we know that the word 'husband' somehow relates to #$wife, but should not be taken to denote it.") :- x_cid(a65b1273c27b5c).
xc_microtheory(a65b1273c27b5c,x_GeneralLexiconMt).
xc_source_file(a65b1273c27b5c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
