x_comment(x_denotesArgInReln,"(#$denotesArgInReln NOUN POS PRED ARG) says that (#$denotation-New NOUN POS TERM), where TERM is the collection of things that are the arg ARG of PRED for any true sentence in which PRED is the arg0.  For example, (#$denotesArgInReln #$Mother-TheWord #$CountNoun #$mother 2) says that one denotation for the word 'mother,' qua #$CountNoun, is the collection of things T such that (#$relationExistsInstance #$mother #$Thing T) -- i.e., the collection of all mothers.  This predicate is useful for linking nouns in the lexicon to *virtual* KB collections, particularly collections we don't necessarily want to have explicitly represented in the KB.") :- x_cid(a65b1273c27b61).
xc_microtheory(a65b1273c27b61,x_GeneralLexiconMt).
