x_comment(x_SimpleWord,"Collection of #$LexicalWords whose #$baseForm cannot be\n\nfurther subdivided into morphemes, where the sub-morphemes are\n\nrecognisable units by native speakers of the language. Example:\n\n#$Run-TheWord.") :- x_cid(a65b1273c27b87).
xc_microtheory(a65b1273c27b87,x_GeneralLexiconMt).
