xc_mapping_rows(a65b1273c27b88,[]).
x_comment(x_CompoundWord,"A #$CompoundWord is a #$LexicalWord which is derived via the\n\n#$MorphologicalProcess #$Compounding-WordFormationProcess. Example: #$Eyesight-TheWord.") :- x_cid(a65b1273c27b89).
xc_microtheory(a65b1273c27b89,x_GeneralLexiconMt).
