x_comment(x_DerivedWordFormingFunction,"#$DerivedWordFormingFunction is the collection of functions\nused for representing derived words. Example: #$WordWithPrefixFn --\n(#$WordWithPrefixFn #$In-Prefix #$Sight-TheWord) is a #$rewriteOf #$Insight-TheWord.") :- x_cid(a65b1273c27b8a).
