x_comment(x_posBaseForms,"(#$posBaseForms WORD POS) represents the different parts of\nspeech that a #$LexicalWord's base form has associated with it. See\n#$baseForm. Example: (#$posBaseForms #$Paint-TheWord #$Verb).") :- x_cid(a65b1273c27b8c).
