x_comment(x_TemporalPrefix,"The collection of prefixes which serve to modify by time or order the meanings of the words they combine with. Example: #$Ex-Pre + #$Husband-TheWord *former husband*.") :- x_cid(a65b1273c27b9e).
xc_microtheory(a65b1273c27b9e,x_GeneralLexiconMt).
