x_comment(x_NLSimpleBinaryConjunctionFn,"(#$NLSimpleBinaryConjunctionFn PHRASE1  PHRASE2) denotes the natural-language phrase formed by concatenating: PHRASE1 'and' PHRASE2. This is viewed as kind of a catch-all for cases where a function for particular types of PHRASE1 and PHRASE2 aren't available. For examples, (#$NLSimpleBinaryConjunctionFn (#$NPIsNP-NLSentenceFn <blah blah blah>) (#$ConcatenatePhrasesFn <blah blah blah>)) is a fine way to conjoin sentences, but if PHRASE1 and PHRASE2 are NP's, #$TermParaphraseFn-NPAndNP is preferred.") :- x_cid(a65b1273c27bb1).
xc_microtheory(a65b1273c27bb1,x_GeneralLexiconMt).
