x_comment('x_TermParaphraseFn-NPAndNP',"(#$TermParaphraseFn-NPAndNP THING1 THING2) denotes the phrase that's essentially (#$ConcatenatePhrasesFn (#$TermParaphraseFn-NP THING1) AND (#$TermParaphraseFn-NP THING2))... typically (#$TermParaphraseFn-NPAndNP :ARG<X> :ARG<Y>), but anything that works for #$TermParaphraseFn-NP will work here.") :- x_cid(a65b1273c27bb2).
xc_microtheory(a65b1273c27bb2,x_GeneralLexiconMt).
