x_comment(x_LinguisticallyImpossibleLexicalWord,"The collection of all lexical words which are not available for use in a language because they are barred from lexicalisation by some linguistic word formation constraint, be it\n\nsyntactic, semantic, phonologic, morphologic, or even pragmatic, of\n\nthe language in question. We could have created the collection LinguisticallyPossibleLexicalWord but this collection is more efficient for browsing and for inferencing since we will generally be specifying the conditions under which something *cannot* be a word, rather than the conditions under which it can; this collection allows us to do so with far fewer rules.") :- x_cid(a65b1273c27bb6).
xc_microtheory(a65b1273c27bb6,x_GeneralLexiconMt).
