x_comment('x_DitransitivePP-ThatClauseFrame',"This frame is used for words that take exactly two complements, the first of which is a PP and the second a that-clause. In HPSG terms: [COMPS  <PP, S[that]>] Example: 'Fred swore to Sally that he would never do it again'.") :- x_cid(a65b1273c27bc8).
xc_microtheory(a65b1273c27bc8,x_GeneralLexiconMt).
