x_comment(x_compoundStringDenotesArgInReln,"(#$compoundStringDenotesArgInReln NOUN LIST POS PRED ARG) says that (#$compoundString NOUN LIST POS TERM), where TERM is the collection of things that are the arg ARG of PRED for any true sentence in which PRED is the arg0.  For example, (#$compoundStringDenotesArgInReln #$Do-TheWord (\"of\" \"evil\") #$AgentiveNoun  \n\n#$sinner 2) says that one denotation for the phrase \"doer(s) of evil,\" is the collection of things T such that (#$relationExistsInstance #$sinner #$Thing T) -- i.e., the collection of all sinners.  This predicate is useful for linking nouns in the lexicon to *virtual* KB collections, particularly collections we don't necessarily want to have explicitly represented in the KB.") :- x_cid(a65b1273c27bcd).
xc_microtheory(a65b1273c27bcd,x_GeneralLexiconMt).
