x_comment('x_firstPersonSg-Past',"(#$firstPersonSg-Past ?WORD ?FORM) means that ?FORM is the past first singular form of ?WORD *and* the past third singular form of ?WORD.  Example:  the #$firstPersonSg-Past form of #$Be-TheWord in English is \"was\" because we have \"I was\" (first singular). In fact, \"was\" may be the only use for this predicate in English.") :- x_cid(a65b1273c27bd7).
