x_comment('x_pluralVerb-Past',"(#$pluralVerb-Past ?WORD ?FORM) means that ?FORM is the past plural form for all  form of ?WORD.  Example:  the past plural form of #$Be-TheWord in English is \"were\" because we have \"you were\" (second plural, second singular), \"they were\" (third plural), and \"we were\" (first plural) but not \"*I were\" (first singular) or \"*he were\" (third singular).  In fact, \"were\" may be the only use for this predicate in English.") :- x_cid(a65b1273c27bd9).
xc_microtheory(a65b1273c27bd9,x_GeneralLexiconMt).
