x_comment(x_BaseWordFormTypeByEndingPhonemeType,"#$BaseWordFormTypeByEndingPhonemeType is the collection of\n\nspecs of #$BaseWordForm which represent #$BaseWordForms according to ending\n\nphoneme type. Example: (#$BaseWordFormsEndingWithPhonemeTypeFn #$Stop-Consonant)\n\nrepresents the collection of #$BaseWordForms ending with a stop.") :- x_cid(a65b1273c27be2).
xc_microtheory(a65b1273c27be2,x_GeneralLexiconMt).
