x_comment(x_phoneticVariantOfPrefix,"(#$phoneticVariantOfPrefix PREFIX STRING BASE-TYPE) means that\n\nSTRING is the #$prefixString of the #$LexicalPrefix PREFIX whenever it is\n\ncombined with a #$BaseWordForm having phonetic feature BASE-TYPE. Example:\n\n(#$phoneticVariantOfPrefix #$In-ThePrefix \"im\" (#$BaseWordFormsStartingWithLetterSequenceFn \"m\"))") :- x_cid(a65b1273c27be3).
xc_microtheory(a65b1273c27be3,x_GeneralLexiconMt).
