x_comment(x_BaseWordFormsStartingWithLetterSequenceFn,"(#$BaseWordFormsStartingWithLetterSequenceFn LETTERS) represents the collection of base word forms beginning with the letter sequence LETTERS. Example: (#$BaseWordFormsStartingWithLetterSequenceFn \"m\") denotes the collection of base word forms beginning with the letter \"m\".") :- x_cid(a65b1273c27be4).
xc_microtheory(a65b1273c27be4,x_GeneralLexiconMt).
