x_comment(x_BaseWordFormsEndingWithLetterSequenceFn,"(#$BaseWordFormsEndingWithLetterSequenceFn LETTERS) represents the collection of base word forms ending with the letter sequence LETTERS. Example: (#$BaseWordFormsEndingWithLetterSequenceFn \"y\") denotes the collection of base word forms ending with the letter \"y\".") :- x_cid(a65b1273c27be5).
xc_microtheory(a65b1273c27be5,x_GeneralLexiconMt).
