x_comment(x_Phoneme,"The collection of #$Phonemes. A phoneme is the smallest unit\n\nof sound which affects the meaning of a word. Different languages have\n\ndifferent phonemes but there are general classes of phonemes which are\n\nused to categorise phonemes across languages. See the specs of this\n\ncollection for those classes. Example: \"ie\" represents an\n\n#$EnglishLanguage #$Diphthong-Vowel, which is a kind of phoneme.") :- x_cid(a65b1273c27be6).
xc_microtheory(a65b1273c27be6,x_GeneralLexiconMt).
xc_source_file(a65b1273c27be6,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27be6,2432).
xc_kb_names(a65b1273c27be6,[]).
xc_mapping_rows(a65b1273c27be6,[]).
x_comment(x_BaseWordFormsStartingWithPhonemeTypeFn,"(#$BaseWordFormsStartingWithPhonemeTypeFn PHONEME-TYPE) represents the collection of base word forms beginning with the phoneme type PHONEME-TYPE. Example: (#$BaseWordFormsStartingWithPhonemeTypeFn #$Labial-Consonant) denotes the collection of base word forms beginning with a labial consonant.") :- x_cid(a65b1273c27be7).
xc_microtheory(a65b1273c27be7,x_GeneralLexiconMt).
xc_source_file(a65b1273c27be7,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
