xc_mapping_rows(a65b1273c27be7,[]).
x_comment(x_BaseWordFormsEndingWithPhonemeTypeFn,"(#$BaseWordFormsEndingWithPhonemeTypeFn PHONEME-TYPE) represents the collection of base word forms ending with the phoneme type PHONEME-TYPE. Example: (#$BaseWordFormsEndingWithPhonemeTypeFn #$LabialConsonant) denotes the collection of base word forms ending with a labial consonant.") :- x_cid(a65b1273c27be8).
xc_microtheory(a65b1273c27be8,x_GeneralLexiconMt).
xc_source_file(a65b1273c27be8,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
