x_comment(x_Consonant,"Collection of #$Consonants. Consonants are those\nsounds produced when something in the vocal tract is obstructing the\nairflow. Example: The English letter \"l\" represents a consonant.") :- x_cid(a65b1273c27be9).
xc_microtheory(a65b1273c27be9,x_GeneralLexiconMt).
xc_source_file(a65b1273c27be9,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
