xc_kb_names(a65b1273c27be9,[]).
xc_mapping_rows(a65b1273c27be9,[]).
x_comment(x_Vowel,"Collection of #$Vowels. Vowel are those\nsounds produced when nothing in the vocal tract is obstructing the\nairflow. Example: The English letter \"a\" represents a vowel.") :- x_cid(a65b1273c27bea).
xc_microtheory(a65b1273c27bea,x_GeneralLexiconMt).
xc_source_file(a65b1273c27bea,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
