xc_kb_names(a65b1273c27bea,[]).
xc_mapping_rows(a65b1273c27bea,[]).
x_comment('x_Stop-Consonant',"Collection of stops. Stops (or plosives) are consonants\nwhere the velum, a valve in your air pipe, is closed before air is\nsuddenly let through. Example: The English letter \"p\" represents a\nstop.") :- x_cid(a65b1273c27beb).
xc_microtheory(a65b1273c27beb,x_GeneralLexiconMt).
xc_source_file(a65b1273c27beb,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27beb,2451).
xc_kb_names(a65b1273c27beb,[]).
xc_mapping_rows(a65b1273c27beb,[]).
x_comment('x_Sonorant-Consonant',"Collection of sonorant consonants. Sonorants are voiced sounds\ncharacterised by relatively free air flow through the vocal tract.\nExample: The English letter \"m\" represents a sonorant consonant.") :- x_cid(a65b1273c27bec).
xc_microtheory(a65b1273c27bec,x_GeneralLexiconMt).
xc_source_file(a65b1273c27bec,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27bec,2455).
xc_kb_names(a65b1273c27bec,[]).
xc_mapping_rows(a65b1273c27bec,[]).
x_comment('x_Fricative-Consonant',"Collection of fricatives. Fricatives (or spriants) are consonants\nwhere the velum, a valve in your air pipe, is not closed, but there is friction when the sound is spoken. Example: The English letter \"f\" represents a\nfricative.") :- x_cid(a65b1273c27bed).
xc_microtheory(a65b1273c27bed,x_GeneralLexiconMt).
xc_source_file(a65b1273c27bed,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27bed,2458).
xc_kb_names(a65b1273c27bed,[]).
xc_mapping_rows(a65b1273c27bed,[]).
x_comment('x_Affricative-Consonant',"Collection of affricatives. Affricatives (or affricates) are made up of two consonants; a stop followed by a fricative. Example: The English letters \"ch\" represents an affricative.") :- x_cid(a65b1273c27bee).
xc_microtheory(a65b1273c27bee,x_GeneralLexiconMt).
xc_source_file(a65b1273c27bee,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27bee,2461).
xc_kb_names(a65b1273c27bee,[]).
xc_mapping_rows(a65b1273c27bee,[]).
x_comment('x_Monophthong-Vowel',"Collection of monophthongs. Monophthongs are vowels where there is a constant sound during pronunciation; the tongue and mouth do not change position. Example: The English letter \"a\" represents a monophthong.") :- x_cid(a65b1273c27bef).
xc_microtheory(a65b1273c27bef,x_GeneralLexiconMt).
xc_source_file(a65b1273c27bef,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27bef,2462).
xc_kb_names(a65b1273c27bef,[]).
xc_mapping_rows(a65b1273c27bef,[]).
x_comment('x_Diphthong-Vowel',"Collection of diphthongs. Diphthongs are vowels where the sound changes during pronunciation; the tongue changes position or the mouth is opened or closed. Example: The English letters \"ou\" represent a diphthong.") :- x_cid(a65b1273c27bf0).
xc_microtheory(a65b1273c27bf0,x_GeneralLexiconMt).
xc_source_file(a65b1273c27bf0,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
