x_comment(x_phoneticVariantOfSuffix,"(#$phoneticVariantOfSuffix SUFFIX STRING BASE-TYPE) means that\n\nSTRING is the #$suffixString of the #$LexicalSuffix SUFFIX whenever it is\n\ncombined with a #$BaseWordForm having phonetic feature BASE-TYPE. Example: (#$phoneticVariantOfSuffix #$Fy-TheSuffix \"ify\" (#$BaseWordFormsEndingWithLetterSequenceFn \"y\"))") :- x_cid(a65b1273c27bf3).
xc_microtheory(a65b1273c27bf3,x_GeneralLexiconMt).
