x_comment(x_NeoClassicalBaseWordForm,"The sub-collection of base morphemes of neo-classical origin. Example: #$Incubate-TheWord.") :- x_cid(a65b1273c27bf4).
xc_microtheory(a65b1273c27bf4,x_GeneralLexiconMt).
