x_comment(x_WordConstituent,"A word constituent is a possible part of a natural language\nword. Examples: Instances of #$LexicalSuffix, #$BaseWordForm and so on.") :- x_cid(a65b1273c27bf5).
xc_microtheory(a65b1273c27bf5,x_GeneralLexiconMt).
