x_comment(x_MorphologicalRuleConstraint,"Collection of constraints relevant during word formation and word analysis.\n\nExample: (#$MorphemeCategorialConstraintFn #$LexicalSuffix\n\n#$DeAdjectivalSuffix) is the #$MorphologicalRuleConstraint that the\n\nelement of a word which is the #$LexicalSuffix must be a\n\n#$DeAdjectivalSuffix.") :- x_cid(a65b1273c27bf6).
xc_microtheory(a65b1273c27bf6,x_GeneralLexiconMt).
xc_source_file(a65b1273c27bf6,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
