xc_mapping_rows(a65b1273c27bf6,[]).
x_comment('x_MorphologicalRuleConstraint-Categorial',"Collection of categorial constraints relevant during word formation and word analysis. Example -- (#$MorphemeCategorialConstraintFn #$LexicalSuffix #$DeAdjectivalSuffix) is the #$MorphologicalRuleConstraint-Categorial that the part of a word which is the #$LexicalSuffix be a #$DeAdjectivalSuffix.") :- x_cid(a65b1273c27bf7).
xc_microtheory(a65b1273c27bf7,x_GeneralLexiconMt).
xc_source_file(a65b1273c27bf7,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
