x_comment('x_MorphologicalRuleConstraint-Semantic',"Collection of semantic constraints relevant during word\n\nformation and word analysis. Example: (#$MorphemeSemanticGenlsConstraintFn #$BaseWordForm\n\n#$Event) is the #$MorphologicalRuleConstraint-Semantic that the #$BaseWordForm of a word denote a spec of #$Event.") :- x_cid(a65b1273c27bf8).
xc_microtheory(a65b1273c27bf8,x_GeneralLexiconMt).
