x_comment(x_DerivationalAffixByBasePOSCategory,"Elements are specs of #$DerivationalAffix categorised\n\naccording to the part of speech instances combine with. Example:\n\nInstances of #$DeAdjectivalSuffix combine with #$Adjectives to form\n\nnew words.") :- x_cid(a65b1273c27bf9).
xc_microtheory(a65b1273c27bf9,x_GeneralLexiconMt).
xc_source_file(a65b1273c27bf9,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
