xc_mapping_rows(a65b1273c27bf9,[]).
x_comment(x_affixRuleCategorialConstraint,"(#$affixRuleCategorialConstraint RULE CONSTRAINT) means that for RULE\n\nto be applicable, CONSTRAINT must be met. Example: if RULE is\n\n#$DerivationalSuffixRule-DeAdjectival, then the #$LexicalSuffix must be a\n\n#$DeAdjectivalSuffix and the base form must be an #$Adjective: (#$affixRuleCategorialConstraint #$DerivationalSuffixRule-DeAdjectival (#$MorphemeCategorialConstraintFn #$LexicalSuffix #$DeAdjectivalSuffix)) and (#$affixRuleCategorialConstraint #$DerivationalSuffixRule-DeAdjectival (#$MorphemeCategorialConstraintFn #$BaseWordForm #$Adjective)).") :- x_cid(a65b1273c27bfa).
xc_microtheory(a65b1273c27bfa,x_GeneralLexiconMt).
xc_source_file(a65b1273c27bfa,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27bfa,2500).
xc_kb_names(a65b1273c27bfa,[]).
xc_mapping_rows(a65b1273c27bfa,[]).
x_comment(x_affixRuleSemanticConstraint,"(#$affixRuleSemanticConstraint RULE CONSTRAINT) means that\n\nfor RULE to be applicable, CONSTRAINT must be met. Example: if RULE is\n\n#$PrefixRule-Degree, then the denotatum of the #$BaseWordForm must be an instance of\n\n#$StandardUnitOfMeasure. (#$affixRuleSemanticConstraint\n\n#$PrefixRule-Degree (#$MorphemeSemanticIsaConstraintFn #$BaseWordForm\n\n#$StandardUnitOfMeasure)).") :- x_cid(a65b1273c27bfb).
xc_microtheory(a65b1273c27bfb,x_GeneralLexiconMt).
xc_source_file(a65b1273c27bfb,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27bfb,2507).
xc_kb_names(a65b1273c27bfb,[]).
xc_mapping_rows(a65b1273c27bfb,[]).
x_comment(x_affixRuleTypeMorphemePosition,"(#$affixRuleTypeMorphemePosition RULE-TYPE N MORPH) means that\n\ninstances of RULE-TYPE are applicable when MORPH is in the Nth position of\n\na word. Example:\n\n(#$affixRuleTypeMorphemePosition #$SuffixRule 2 #$LexicalSuffix) means that for a suffix rule to be relevant to a word, an instance of #$LexicalSuffix must be the second element of the word.") :- x_cid(a65b1273c27bfc).
xc_microtheory(a65b1273c27bfc,x_GeneralLexiconMt).
xc_source_file(a65b1273c27bfc,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27bfc,2518).
xc_kb_names(a65b1273c27bfc,[]).
xc_mapping_rows(a65b1273c27bfc,[]).
x_comment(x_affixRuleArity,"(#$affixRuleArity RULE N) means that any word to which\n\n#$AffixRule RULE applies consists of exactly N word constituents.\n\nExample: (#$affixRuleArity #$DerivationalSuffixRule-DeAdjectival 2) ") :- x_cid(a65b1273c27bfd).
xc_microtheory(a65b1273c27bfd,x_GeneralLexiconMt).
xc_source_file(a65b1273c27bfd,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27bfd,2525).
xc_kb_names(a65b1273c27bfd,[]).
xc_mapping_rows(a65b1273c27bfd,[]).
x_comment(x_affixRuleResultPOS,"(#$affixRuleResultPOS RULE POS) means that a word created as\n\na result of the morphological process described in RULE has part of\n\nspeech POS. Example: (#$affixRuleResultPOS\n\n#$DerivationalSuffixRule-Adjective #$Adjective) means that combining an\n\n#$AdjectiveProducingSuffix with some other morpheme will result in an\n\n#$Adjective.") :- x_cid(a65b1273c27bfe).
xc_microtheory(a65b1273c27bfe,x_GeneralLexiconMt).
xc_source_file(a65b1273c27bfe,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27bfe,2530).
xc_kb_names(a65b1273c27bfe,[]).
xc_mapping_rows(a65b1273c27bfe,[]).
x_comment(x_derivationalAffixResultPOS,"(#$derivationalAffixResultPOS AFFIX POS) means that the #$DerivationalAffix AFFIX combines with #$BaseWordForms to create words with part of speech POS. Example: (#$derivationalAffixResultPOS #$Ate-TheSuffix #$Verb) means that the #$DerivationalSuffix #$Ate-TheSuffix combines with #$BaseWordForms to create #$Verbs, e.g. \"hyphenate\"") :- x_cid(a65b1273c27bff).
xc_microtheory(a65b1273c27bff,x_GeneralLexiconMt).
xc_source_file(a65b1273c27bff,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
