xc_kb_names(a65b1273c27bff,[]).
xc_mapping_rows(a65b1273c27bff,[]).
x_comment(x_derivationalAffixBasePOS,"(#$derivationalAffixBasePOS AFFIX POS) means that the #$DerivationalAffix AFFIX combines with #$BaseWordForms with part of speech POS. Example: (#$derivationalAffixBasePOS #$En-TheSuffix #$Adjective) means that the #$LexicalSuffix #$En-TheSuffix combines with #$Adjectives, e.g. \"lighten\"") :- x_cid(a65b1273c27c00).
xc_microtheory(a65b1273c27c00,x_GeneralLexiconMt).
