xc_mapping_rows(a65b1273c27c00,[]).
x_comment(x_wordHasConstituent,"(#$wordHasConstituent WORD CONSTITUENT) means that the\n\n#$LexicalWord WORD has CONSTITUENT as a #$WordConstituent. Example:\n\n(#$wordHasConstituent (#$WordWithSuffixFn #$Joy-TheWord #$Ful_AdjectiveProducing-TheSuffix) #$Joy-TheWord) and (#$wordHasConstituent (#$WordWithSuffixFn #$Joy-TheWord #$Ful_AdjectiveProducing-TheSuffix) #$Ful_AdjectiveProducing-TheSuffix) means that the word (#$WordWithSuffixFn #$Joy-TheWord #$Ful_AdjectiveProducing-TheSuffix) has two constituents; the #$BaseWordForm #$Joy-TheWord and the #$LexicalSuffix #$Ful_AdjectiveProducing-TheSuffix. Note that GAFs using this predicate are not assertible; they are inferred from the state of the knowledge in the KB. See specPreds for what to use in assertions") :- x_cid(a65b1273c27c01).
xc_microtheory(a65b1273c27c01,x_GeneralLexiconMt).
