x_comment(x_MorphemeSemanticIsaConstraintFn,"(#$MorphemeSemanticIsaConstraintFn ELEMENT-TYPE THING)\n\nrepresents the constraint that the part of a word of type ELEMENT-TYPE\n\ndenote an instance of THING. Example: (#$MorphemeSemanticIsaConstraintFn\n\n#$BaseWordForm #$StandardUnitOfMeasure) represents the constraint that a\n\n#$BaseWordForm denote an instance of #$StandardUnitOfMeasure.") :- x_cid(a65b1273c27c03).
xc_microtheory(a65b1273c27c03,x_GeneralLexiconMt).
