x_comment(x_BasePOSDerivationalAffixRule,"The rule which represents the base word part of speech constraints imposed by affixes. Example: (#$affixRuleCategorialConstraint #$BasePOSDerivationalAffixRule (#$MorphemeCategorialConstraintFn #$DeverbalAffix #$Verb)) states that if a word is derived using a #$DeverbalAffix,  then the base word must be a #$Verb.") :- x_cid(a65b1273c27c05).
