x_comment(x_variantOfPrefix,"(#$variantOfPrefix PREFIX STRING) means that STRING is another possible #$prefixString of the #$LexicalPrefix PREFIX. Example: (#$variantOfPrefix #$In-ThePrefix \"im\"). Whenever possible, specify the conditions under which variant spellings become relevant by using one of the specPredsWRTArgs preds instead, e.g. (#$phoneticVariantOfPrefix #$In-ThePrefix \"im\" (#$BaseWordFormsStartingWithLetterSequenceFn \"m\")).") :- x_cid(a65b1273c27c0a).
