x_comment(x_variantOfSuffix,"(#$variantOfSuffix SUFFIX STRING) means that STRING is another possible #$suffixString of the #$LexicalSuffix SUFFIX. Example: (#$variantOfSuffix #$Ion_ConcreteNounProducing-TheSuffix \"ition\"). Whenever possible, specify the conditions under which variant spellings become relevant by using one of the specPredsWRTArgs preds instead, e.g. (#$phoneticVariantOfSuffix #$Ion_ConcreteNounProducing-TheSuffix \"ition\" (#$BaseWordFormsEndingWithLetterSequenceFn \"ine\")).") :- x_cid(a65b1273c27c0b).
