x_comment(x_ProductiveLexicalAffix,"Collection of derivational affixes which are currently used\nin the derivation of new words. Example: #$Un_Neg-ThePrefix is\nfrequently used in English today in word creation --\n#$Unsteady-TheWord.") :- x_cid(a65b1273c27c0c).
