x_comment(x_UnproductiveLexicalAffix,"Collection of derivational affixes which are no longer used\nin the derivation of new words. Example: The prefix \"be\" as in\n\"beget\" is no longer (or very infrequently) used in English word\ncreation today.") :- x_cid(a65b1273c27c0d).
