x_comment(x_LevelOneAffix,"#$LevelOneAffixes (sometimes called \"Class 1 affixes\" or\n\"primary affixes\") are the affixes which attach to roots during the\nfirst level of word formation (see #$cyclistNotes). #$LevelOneAffixes\ncause a stress shift in the resulting word. Example: \"Dar*win*ian\".") :- x_cid(a65b1273c27c0f).
