x_comment(x_NounProducingAffix,"The collection of affixes which serve to convert words into #$Nouns. Example: #$Friend-TheWord + #$Ship-TheSuffix = #$Friendship-TheWord.") :- x_cid(a65b1273c27c22).
xc_microtheory(a65b1273c27c22,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c22,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c22,2641).
xc_kb_names(a65b1273c27c22,[]).
xc_mapping_rows(a65b1273c27c22,[]).
x_comment(x_morphologicalConstraintRelevantToWord,"(#$morphologicalConstraintRelevantToWord CONSTRAINT WORD)\n\nmeans that the #$MorphologicalRuleConstraint CONSTRAINT applies\n\nto the #$LexicalWord WORD. For example, a CONSTRAINT such as\n\n(#$MorphemeCategorialConstraintFn #$DeverbalAffix #$Verb) is relevant to all words which are derived with deverbal affixes.") :- x_cid(a65b1273c27c23).
xc_microtheory(a65b1273c27c23,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c23,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c23,2642).
xc_kb_names(a65b1273c27c23,[]).
xc_mapping_rows(a65b1273c27c23,[]).
x_comment(x_WordConstituentsDerivationalPrefixRule,"The rule which represents the general word constituent constraints imposed by prefixes. For example, if a word is derived using a prefix, then there must be two word constituents, a base word and a prefix.") :- x_cid(a65b1273c27c24).
xc_microtheory(a65b1273c27c24,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c24,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c24,2649).
xc_kb_names(a65b1273c27c24,[]).
xc_mapping_rows(a65b1273c27c24,[]).
x_comment(x_WordConstituentsDerivationalSuffixRule,"The rule which represents the general word constituent constraints imposed by suffixes. For example, if a word is derived using a suffix, then there must be two word constituents, a base word and a suffix.") :- x_cid(a65b1273c27c25).
xc_microtheory(a65b1273c27c25,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c25,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c25,2650).
xc_kb_names(a65b1273c27c25,[]).
xc_mapping_rows(a65b1273c27c25,[]).
x_comment(x_affixSemantics,"(#$affixSemantics AFFIX NAT) means that the\n\n#$CycLNonAtomicTerm NAT is the semantic template which will be used in determining the semantic interpretation of a word\n\nwith constituent #$LexicalAffix AFFIX. There will be a #$SubLKeyword in\n\none or more positions in NAT. Which keywords are valid for which\n\naffix is represented by #$affixKeywords. Example: (#$affixSemantics #$Un_Neg-ThePrefix (#$InstanceWithRelationToFn #$AttributeValue #$oppositeAttributes :BASE-WORD-DENOT)) says that any word #$derivedUsingPrefix #$Un_Neg-ThePrefix will denote the opposite attribute of that denoted by the base word it is #$morphologicallyDerivedFrom. For example, the word (#$WordWithPrefixFn #$Un_Neg-ThePrefix #$Happy-TheWord) will denote (#$InstanceWithRelationToFn #$AttributeValue #$oppositeAttributes (#$MediumToVeryHighAmountFn #$Happiness)) since (#$generalSemantics #$Happy-TheWord (#$MediumToVeryHighAmountFn #$Happiness)).") :- x_cid(a65b1273c27c26).
xc_microtheory(a65b1273c27c26,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c26,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c26,2651).
xc_kb_names(a65b1273c27c26,[]).
xc_mapping_rows(a65b1273c27c26,[]).
x_comment(x_ConcreteNounProducingSuffix,"The collection of suffixes which serve to convert words into concrete nouns. These are generally #$CountNouns. Example: #$Appoint-TheWord + #$Ee_Deverb-TheSuffix = #$Appointee-TheWord.") :- x_cid(a65b1273c27c27).
xc_microtheory(a65b1273c27c27,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c27,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c27,2660).
xc_kb_names(a65b1273c27c27,[]).
xc_mapping_rows(a65b1273c27c27,[]).
x_comment(x_AbstractNounProducingSuffix,"The collection of suffixes which serve to convert words into abstract nouns. These are generally #$MassNouns. Example: #$Friend-TheWord + #$Ship-TheSuffix = #$Friendship-TheWord.") :- x_cid(a65b1273c27c28).
xc_microtheory(a65b1273c27c28,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c28,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c28,2661).
xc_kb_names(a65b1273c27c28,[]).
xc_mapping_rows(a65b1273c27c28,[]).
x_comment(x_OpenClassWord,"The collection of all words which are members of open lexical classes, namely those with a potentially unlimited membership. The open lexical classes are #$Adjectives, #$Nouns, #$Verbs, #$Adverbs.") :- x_cid(a65b1273c27c29).
xc_microtheory(a65b1273c27c29,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c29,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c29,2662).
xc_kb_names(a65b1273c27c29,[]).
xc_mapping_rows(a65b1273c27c29,[]).
x_comment('x_presentTense-Universal',"(#$presentTense-Universal WU STRING) means that the present tense form of WU, regardless of number or person, is STRING.") :- x_cid(a65b1273c27c2a).
xc_microtheory(a65b1273c27c2a,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c2a,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c2a,2663).
xc_kb_names(a65b1273c27c2a,[]).
xc_mapping_rows(a65b1273c27c2a,[]).
x_comment(x_webFrequencyForLexicalAssertion,"(#$webFrequencyForLexicalAssertion AS N) means that a string generated from AS is expected to appear in any sufficiently large Web corpus of documents in the language appropriate for AS with approximate frequency N, where N is a normalized score from 0 to 99 such that differences are exaggerated at the low end and minimized at the high end.") :- x_cid(a65b1273c27c2b).
xc_microtheory(a65b1273c27c2b,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c2b,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c2b,2664).
xc_kb_names(a65b1273c27c2b,[]).
xc_mapping_rows(a65b1273c27c2b,[]).
x_comment(x_bogusSpeechPart,"(#$bogusSpeechPart POS) means that the #$SpeechPart POS is\n\nnot a bona fide part of speech, but that we find it useful in certain\n\ncases to represent it as such in our ontology. One consequence of\n\nidentifying a #$SpeechPart as a #$bogusSpeechPart is that it will not\n\nbe treated as a #$SpeechPart when the morphological parser is used in\n\nparsing.") :- x_cid(a65b1273c27c2c).
xc_microtheory(a65b1273c27c2c,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c2c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c2c,2665).
xc_kb_names(a65b1273c27c2c,[]).
xc_mapping_rows(a65b1273c27c2c,[]).
x_comment(x_semanticallyRelatedAffixes,"(#$semanticallyRelatedAffixes AFFIX1 AFFIX2 ... AFFIXN)\n\nmeans that the #$LexicalAffixes (AFFIX1 AFFIX2 ... AFFIXN) are subtle\n\nsemantic variants of one another but they all share the same\n\n#$affixString. The differences will generally be found in the\n\n#$derivationalAffixBasePOS, the #$derivationalAffixResultPOS, and the\n\n#$affixSemantics. Example: #$Ese_NounProducing-TheSuffix\n\n#$Ese_AdjectiveProducing-TheSuffix are so related.") :- x_cid(a65b1273c27c2d).
xc_microtheory(a65b1273c27c2d,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c2d,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c2d,2676).
xc_kb_names(a65b1273c27c2d,[]).
xc_mapping_rows(a65b1273c27c2d,[]).
x_comment(x_exceptionForSemTransTemplate,"(#$exceptionForSemTransTemplate WORD COL) means that the\n\n#$LexicalWord WORD should be treated as an exception for all\n\nsemtranstemplates whose arg1 is the collection COL. Example:\n\n(#$exceptionForSemTransTemplate #$Skinny-TheWord\n\n#$PhysiologicalAttribute) means that any semTranses involving the word\n\n#$Skinny-TheWord which could be inferred from semTransTemplates for\n\n#$PhysiologicalAttribute should not be inferred. This predicate is\n\nused for making exceptions to semTransTemplates explicit, a better\n\nalternative to just blasting unwanted inferences which will return\n\nwhen the rules are repropagated.") :- x_cid(a65b1273c27c2e).
xc_microtheory(a65b1273c27c2e,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c2e,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c2e,2689).
xc_kb_names(a65b1273c27c2e,[]).
xc_mapping_rows(a65b1273c27c2e,[]).
x_comment(x_TheRNPParse,"#$TheRNPParse is an #$IntermediateVocabFunction that is used to organize the parse of an NP containing a relative clause into a form which can be reformulated into assertible CycL. (#$TheRNPParse TAGGEDNP COL) denotes that #$IntermediateVocabTerm that can be processed by the #$CycLReformulator in the way prescribed by the relevant #$reformulatorEquiv and #$reformulatorEquals assertions.") :- x_cid(a65b1273c27c2f).
xc_microtheory(a65b1273c27c2f,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c2f,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c2f,2708).
xc_kb_names(a65b1273c27c2f,[]).
xc_mapping_rows(a65b1273c27c2f,[]).
x_comment(x_followsFromPrecedingDiscourse,"#$followsFromPrecedingDiscourse is a natural-language-based predicate that applies to a single propositional argument. (#$followsFromPrecedingDiscourse PROP) means that PROP follows logically from the immediately preceding statements in a discourse context. In English it can be rendered as \"Therefore, PROP\", or \"Q.E.D. PROP\".") :- x_cid(a65b1273c27c30).
xc_microtheory(a65b1273c27c30,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c30,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c30,2709).
xc_kb_names(a65b1273c27c30,[]).
xc_mapping_rows(a65b1273c27c30,[]).
x_comment(x_SemTransTemplatePredicate,"The specialization of #$NLSemanticPredicate whose instances map groups of words (classified semantically) to #$NLTemplateExpressions.") :- x_cid(a65b1273c27c31).
xc_microtheory(a65b1273c27c31,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c31,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c31,2710).
xc_kb_names(a65b1273c27c31,[]).
xc_mapping_rows(a65b1273c27c31,[]).
x_comment('x_CollectionLexificationPredicate-Required',"The collection of predicates such that if a #$CycCollection COL is lexified using one of these predicates, COL is deemed *lexified*.") :- x_cid(a65b1273c27c32).
xc_microtheory(a65b1273c27c32,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c32,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c32,2711).
xc_kb_names(a65b1273c27c32,[]).
xc_mapping_rows(a65b1273c27c32,[]).
x_comment(x_infersParseTemplate,"(#$infersParseTemplate RELATION) means that the usual requirement that a CycL relation have an assertion associating it with a natural language template (these are usually made in the form of #$assertTemplate-Reln RELATION ...) does not apply because a parse template on a #$genlPreds of RELATION should be used during parsing instead. Example: #$hasAttributes does not need a parse template assertion since all of the ways one would make the assertion (#$hasAttributes X Y) in NL apply equally to a #$genlPreds of #$hasAttributes, #$is-Underspecified. In these cases we want to parse to the general term and reason to the more specific level. For example, if we know that Y is an attribute, then we'll use (#$hasAttributes X Y) rather than (#$is-Underspecified X Y) in the final CycL. These assertions will be used in NL quality control to determine whether a relation is appropriately lexified.") :- x_cid(a65b1273c27c33).
xc_microtheory(a65b1273c27c33,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c33,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c33,2712).
xc_kb_names(a65b1273c27c33,[]).
xc_mapping_rows(a65b1273c27c33,[]).
x_comment(x_PercentParaphraseFn,"(#$PercentParaphraseFn NUM) denotes the\n(possibly contextually dependent) best natural-language word\nor phrase treating NUM as a percentage. For instance (#$PercentParaphraseFn .25) is likely to come out as \"25%\".") :- x_cid(a65b1273c27c34).
xc_microtheory(a65b1273c27c34,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c34,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c34,2713).
xc_kb_names(a65b1273c27c34,[]).
xc_mapping_rows(a65b1273c27c34,[]).
x_comment('x_holds-Underspecified',"(holds-Underspecified ARG1 ARG2) means that ARG1 in some\nunderspecified sense (perhaps metaphorically or non-spatially) 'holds'\nARG2.  Important spec preds include #$educationLevel (Consider\n'Chip holds a PhD') and #$jobPositionHasPositionType ('US Senators\nhold US Senate seats').") :- x_cid(a65b1273c27c35).
xc_microtheory(a65b1273c27c35,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c35,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c35,2716).
xc_kb_names(a65b1273c27c35,[]).
xc_mapping_rows(a65b1273c27c35,[]).
x_comment('x_supports-Underspecified',"(#$supports-Underspecified ARG1 ARG2) says that ARG1, in some underspecified or perhaps metaphorical sense, 'supports' ARG2.") :- x_cid(a65b1273c27c36).
xc_microtheory(a65b1273c27c36,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c36,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c36,2721).
xc_kb_names(a65b1273c27c36,[]).
xc_mapping_rows(a65b1273c27c36,[]).
x_comment(x_doesntNeedParseTemplate,"(#$doesntNeedParseTemplate RELATION) means that the usual requirement\nthat a CycL relation have an assertion associating it with a natural language\ntemplate (these are usually made in the form of #$assertTemplate-Reln\nRELATION ...) does not apply. #$infersParseTemplate is an important specPred of this term.") :- x_cid(a65b1273c27c37).
xc_microtheory(a65b1273c27c37,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c37,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c37,2722).
xc_kb_names(a65b1273c27c37,[]).
xc_mapping_rows(a65b1273c27c37,[]).
x_comment('x_dependsOn-Underspecified',"(#$dependsOn-Underspecified ARG1 ARG2) means that ARG1, in\nsome underspecified sense, depends on ARG2.  Consider 'CHILD depends on\nFATHER' as well as 'TASK1 depends on TASK2'. Use one of the specPreds for making assertions.") :- x_cid(a65b1273c27c38).
xc_microtheory(a65b1273c27c38,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c38,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c38,2726).
xc_kb_names(a65b1273c27c38,[]).
xc_mapping_rows(a65b1273c27c38,[]).
x_comment('x_genStringAssertion-Terse',"(#$genStringAssertion-Terse TERM LEX) means that the lexical assertion LEX is a terse lexification for TERM. Such an assertion will often indicate that the use of LEX is somehow context dependent. For example, in a military context where courses of action are being discussed, generating the term #$coaSimplicity as \"simplicity\" as opposed to the wordier \"simplicity of the COA\" might be preferrable since the \"of the COA\" part is implied by the context of discussion. To have a terse lexification for a term used in generation, use the #$TerseParaphraseFn function in your #$genTemplate assertion. Lexical assertions marked with the #$genStringAssertion-Terse meta-assertion will only be used in generation under two circumstances: 1. When a #$TerseParaphraseFn function calls for one and 2. When no other lexificatin for TERM exists.") :- x_cid(a65b1273c27c39).
xc_microtheory(a65b1273c27c39,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c39,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c39,2729).
xc_kb_names(a65b1273c27c39,[]).
xc_mapping_rows(a65b1273c27c39,[]).
x_comment(x_TensedPhraseFn,"(#$TensedPhraseFn TEMPORAL-THING PHRASE) denotes the\n(typically contextually dependent) natural language word or\nphrase PHRASE, while specifying a linguistic constraint on\nits tense. Namely, the linguistic context requires that PHRASE's tense\nbe appropriate for denoting a situation cotemporal with TEMPORAL-THING. For instance, in a typical English-language\ncontext, (#$TensedPhraseFn #$Yesterday-Indexical\n(#$BestNLWordFormOfLexemeFn #$Eat-TheWord)) would denote the\n#$SententialConstituent instantiated by the string 'ate'.") :- x_cid(a65b1273c27c3a).
xc_microtheory(a65b1273c27c3a,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c3a,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c3a,2730).
xc_kb_names(a65b1273c27c3a,[]).
xc_mapping_rows(a65b1273c27c3a,[]).
x_comment('x_TensedPhraseFn-DefaultPast',"(#$TensedPhraseFn-DefaultPast TEMPORAL-THING PHRASE) is just like #$TensedPhraseFn, except that it defaults to past tense when TEMPORAL-THING cannot be established to be cotemporal with or subsequent to the time of utterance.") :- x_cid(a65b1273c27c3b).
xc_microtheory(a65b1273c27c3b,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c3b,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c3b,2738).
xc_kb_names(a65b1273c27c3b,[]).
xc_mapping_rows(a65b1273c27c3b,[]).
x_comment('x_ConcatenatePhrasesFn-NoSpaces',"Just like #$ConcatenatePhrasesFn, except no spaces are added between phrases.") :- x_cid(a65b1273c27c3c).
xc_microtheory(a65b1273c27c3c,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c3c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c3c,2739).
xc_kb_names(a65b1273c27c3c,[]).
xc_mapping_rows(a65b1273c27c3c,[]).
x_comment(x_DefiniteNbarPPFn,"(#$DefiniteNbarPPFn PHRASE STRING PHRASE) denotes the - contextually best - definite NP of the form 'the PHRASE STRING PHRASE'. The first phrase is typically an Nbar.") :- x_cid(a65b1273c27c3d).
xc_microtheory(a65b1273c27c3d,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c3d,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c3d,2740).
xc_kb_names(a65b1273c27c3d,[]).
xc_mapping_rows(a65b1273c27c3d,[]).
x_comment(x_IndefiniteNbarPPFn,"(#$IndefiniteNbarPPFn PHRASE STRING PHRASE) denotes the - contextually best - indefinite NP of the form 'a PHRASE STRING PHRASE'. The first phrase is typically an Nbar.") :- x_cid(a65b1273c27c3e).
xc_microtheory(a65b1273c27c3e,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c3e,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c3e,2741).
xc_kb_names(a65b1273c27c3e,[]).
xc_mapping_rows(a65b1273c27c3e,[]).
x_comment(x_Postmodifier_EdFormFn,"(Postmodifier_EdFormFn VERB PREP PHRASE) generates a clause of the form 'perfect(VERB) PREP PHRASE'. For example, used in a genTemplate, (#$Postmodifier_EdFormFn #$Buy-TheWord #$With-TheWord (#$BestDetNbarFn-Indefinite :ARG1)) would typically generate as 'bought with some ARG1'.") :- x_cid(a65b1273c27c3f).
xc_microtheory(a65b1273c27c3f,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c3f,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c3f,2742).
xc_kb_names(a65b1273c27c3f,[]).
xc_mapping_rows(a65b1273c27c3f,[]).
x_comment(x_NbarHeadedByNounFormFn,"(#$NbarHeadedByNounFormFn NOUN FORM CLAUSE) generates the best N-Bar 'FORM(NOUN) CLAUSE'. For example, (#$NbarHeadedByNounFormFn #$Projectile-TheWord #$plural-Generic (#$Postmodifier_EdFormFn #$Fire-TheWord #$From-TheWord (#$BestDetNbarFn-Indefinite :ARG1))) would typically generate as 'projectiles fired from some [ARG1]'.") :- x_cid(a65b1273c27c40).
xc_microtheory(a65b1273c27c40,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c40,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c40,2743).
xc_kb_names(a65b1273c27c40,[]).
