x_comment(x_GenTemplateRecipeOmitsArgFn,"(#$GenTemplateRecipeOmitsArgFn :ARGX RECIPE) licenses the omission of :ARGX from a #$GenTemplateRecipe. For example, in (#$genTemplate-Constrained #$ScientificNumberFn (#$isa :SELF #$CycLClosedNonAtomicTerm) (#$GenTemplateRecipeOmitsArgFn :ARG1 (#$GenTemplateRecipeOmitsArgFn :ARG2 (#$BestBindingsPhraseFn (#$evaluate ?STRING (#$ScientificNumberToStringFn :SELF)) (#$BestNLPhraseOfStringFn ?STRING))))), the #$GenTemplateRecipeOmitsArgFn's allow the recipe itself to omit :ARG1 and :ARG2, which it in fact does.") :- x_cid(a65b1273c27c47).
xc_microtheory(a65b1273c27c47,x_GeneralLexiconMt).
