x_comment(x_nlPragmaticRequirement,"A MetaKnowledgePredicate that is used to place a pragmatic precondition on the use of a lexical assertion (see #$CycLNLAssertion -- not yet supported). (#$nlPragmaticRequirement CONDITION\nNL_ASSERTION) says that the lexical assertion NL_ASSERTION should be\nused only in circumstances which meet CONDITION. Example: (#$nlPragmaticRequirement (#$pragmaticallyAcceptable #$SlangSpeech) (#$denotation #$Veep-TheWord #$CountNoun 0 #$VicePresident-GovernmentOfficial)) says the denotation should be used in dialogue situations which allow for slang speech.") :- x_cid(a65b1273c27c4b).
xc_microtheory(a65b1273c27c4b,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c4b,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
