x_comment(x_nlPragmaticRequirement,"A MetaKnowledgePredicate that is used to place a pragmatic\nprecondition on the use of a lexical assertion (see #$CycLNLAssertion\n-- not yet supported, BUG #4905). (#$nlPragmaticRequirement CONDITION\nNL_ASSERTION) says that the lexical assertion NL_ASSERTION should be\npreferred in circumstances which meet CONDITION. Example: (#$nlPragmaticRequirement (#$indexicalReferent (#$TheFn #$FormalityOfSpeech)  #$SlangSpeech) (#$denotation #$Veep-TheWord #$CountNoun 0 #$VicePresident-GovernmentOfficial)) says the denotation should be used in dialogue situations which allow for slang speech.") :- x_cid(a65b1273c27c4c).
xc_microtheory(a65b1273c27c4c,x_GeneralLexiconMt).
