x_comment(x_uninflectedWordStrings,"(#$uninflectedWordStrings WORD STRING) states that STRING is one of the strings for the word unit WORD in some microtheory.  In other words, some #$SpeechPartPredicate is used on WORD to relate it to STRING. This is a stronger version of #$wordStrings in that the code will use it as a shortcut for parsing and generating uninflected words such as #$Adverbs and #$Pronouns (given that the various forms of pronouns are, at least for English, ontologized as separate word units). By 'uninflected' we mean that it doesn't show number or gender agreement; in principle, the word could still vary based on case. This predicate is #$notAssertible since it is concluded from the current state of the knowledge base.") :- x_cid(a65b1273c27c4d).
xc_microtheory(a65b1273c27c4d,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c4d,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
xc_source_line(a65b1273c27c4d,2771).
xc_kb_names(a65b1273c27c4d,[]).
xc_mapping_rows(a65b1273c27c4d,[]).
x_comment(x_pragmaticallyAcceptable,"#$pragmaticallyAcceptable is a natural-language-based predicate that applies to a single pragmatic attribute argument. (#$pragmaticallyAcceptable ATTR) means that ATTR is an acceptable pragmatic attribute for speech in the current dialog context, i.e. that the addressee should not be shocked or surprised if the speaker uses speech characterized by ATTR. It is #$notAssertible, because its value depends on the current dialog context.") :- x_cid(a65b1273c27c4e).
xc_microtheory(a65b1273c27c4e,x_GeneralLexiconMt).
xc_source_file(a65b1273c27c4e,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GeneralLexiconMt.krf').
