x_comment(x_inducedTypicalSubjectTypeOfVerb,"(#$inducedTypicalSubjectTypeOfVerb VERB-STRING COLLECTION) means that, according to statistical analysis of some text corpus (like, perhaps, the New York Times from 2001), the typical subject of the verb VERB-STRING is COLLECTION.  For example, (#$inducedTypicalSubjectTypeOfVerb \"bloom\" #$PlantBLO) means that #$PlantBLOs are the things that are most typically said to bloom.  Use infinitive verb forms in queries.") :- x_cid(a65b1273c27c52).
xc_microtheory(a65b1273c27c52,x_GeneralLexiconMt).
