x_comment(x_TheNCArgIsas,"#$TheNCArgIsas is a special kind of term whose only purpose is to be used in #$ELSentence-Assertibles that appear as the second argument of an #$ncRuleConstraint. It is a directive to the code to replace the keyword with the maximal #$argIsas of the #$BinaryPredicate, for the appropriate N, of a subcollection nat. For example, the assertion (#$ncRuleConstraint #$TerrorismExpert-NCR (#$SubcollectionOfWithRelationToFn #$TheNCArgIsas #$TheNCHead #$TheNCModifier)) means that one of the conditions on the application of the #$NounCompoundRule #$TerrorismExpert-NCR is that the 'from' arg conform to the #$arg1Isas of the #$BinaryPredicate, e.g., \"terrorism expert\" would map to (#$SubcollectionOfWithRelationToFn #$IntelligentAgent #$expertRegarding #$TerroristAct).") :- x_cid(a65b1273c27c5a).
xc_microtheory(a65b1273c27c5a,x_GeneralLexiconMt).
