xc_mapping_rows(a65b1273c27c5a,[]).
x_comment(x_TheNCArgGenls,"#$TheNCArgGenls is a special kind of term whose only purpose is to be used in #$ELSentence-Assertibles that appear as the second argument of an #$ncRuleConstraint. It is a directive to the code to replace the keyword with the maximal #$argGenls of the #$BinaryPredicate, for the appropriate N, of a subcollection nat. For example, the assertion (#$ncRuleConstraint TerroristWeapon-NCR (#$SubcollectionOfWithRelationToFn #$TheNCModifier #$TheNCHead #$TheNCArgGenls)) means that one of the conditions on the application of the #$NounCompoundRule TerroristWeapon-NCR is that the 'to' arg conform to the #$arg2Genls of the #$BinaryPredicate, e.g., \"terrorist device\" might map to (#$SubcollectionOfWithRelationToFn #$TerroristAct #$deviceTypeUsed #$PhysicalDevice).") :- x_cid(a65b1273c27c5b).
xc_microtheory(a65b1273c27c5b,x_GeneralLexiconMt).
