x_comment(x_parsingConflateTo,"A predicate relating two terms that are too close in meaning for the distinction between them to matter when doing any sort of Natural Language Understanding task. (parsingConflateTo DISPREFERRED-TERM PREFERRED-TERM) means that any parse using DISPREFERRED-TERM should be disfavored relative to a parse containing PREFERRED-TERM.  This is in effect saying that the two terms are close enough in meaning that TERM1 should be treated exactly like TERM2 for the purpose of NL Understanding.  A good example of this is the distinction between #$Motive and (#$SubcollectionOfWithRelationFromTypeFn #$Motive #$actionMotives #$Action).  This is a distinction which is fine to have in the KB, but not helpful for NLU purposes.") :- x_cid(a65b1273c27c82).
xc_microtheory(a65b1273c27c82,x_GeneralLexiconMt).
