x_comment('x_simplePast-Generic',"(#$simplePast-Generic WORD FORM) means that FORM is a simple-aspect past-tense form of WORD for at least one person number combination (possibly not all).  Contrast this with the meaning of #$pastTense-Universal.  People writing #$genTemplates should use #$simplePast-Generic instead of #$pastTense-Universal, especially with #$Be-TheWord, because there are two different simple past forms of #$Be-TheWord, \"was\" and \"were\" -- there is no #$pastTense-Universal form of #$Be-TheWord.  For example, to request a simple past form of #$Be-TheWord, use something equivalent to (#$PhraseFormFn #$simplePast-Generic #$Be-TheWord).") :- x_cid(a65b1273c27c88).
xc_microtheory(a65b1273c27c88,x_GeneralLexiconMt).
