x_comment(x_TypeClarifyingPhraseFn,"(#$TypeClarifyingPhraseFn TYPE-CLARIFYING-PHRASE MAIN-PHRASE) denotes a noun phrase consisting at least of MAIN-PHRASE.  It may also contain TYPE-CLARIFYING-PHRASE but only if the MAIN-PHRASE is not informative as to the type of the object(s) in question.  For example, when variables are paraphrased explicitly, the type-clarifying phrase should appear.  So (#$TypeClarifyingPhraseFn (#$BestNLPhraseOfStringFn \"the medical diagnosis\") (#$TermParaphraseFn-NP :ARG1)) will come out as \"the medical diagnosis ?X\" if :ARG1 is ?X and ?X is paraphrased as \"?X\".  If ?X is paraphrased as, for example, \"some medical diagnosis\", then the clarifying phrase should not appear.") :- x_cid(a65b1273c27c9d).
